33	      // honoring backslash escapes so an escaped quote doesn't end it early.
34	      out += c;
35	      if (c === '\\') { out += c2 ?? ''; i++; }
36	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
