// Helpers for checks that scan source *code* for a forbidden token (a banned
// API, an impure import, a DOM specific). Such a check must see code, not
// prose: a comment or a doc-string that merely *names* `chrome.storage` or
// `fetch(` is describing the code, not doing it, and matching it is a false
// positive that fails the build over an English sentence. Strip comments first.

// Return `source` with its JS/TS comments removed, leaving everything else —
// including string and template literals — byte-for-byte intact. String-aware
// on purpose: a `//` inside "https://…" is not a comment, and dropping the rest
// of that line would corrupt real code (and could hide a genuine violation that
// follows on the same line). Regex literals are treated as code and preserved.
// Newlines inside block comments are kept so line numbers don't shift.
export function stripComments(source) {
  let out = '';
  let state = 'code'; // code | line | block | sq | dq | tpl
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    const c2 = source[i + 1];
    if (state === 'code') {
      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
      if (c === "'") state = 'sq';
      else if (c === '"') state = 'dq';
      else if (c === '`') state = 'tpl';
      out += c;
    } else if (state === 'line') {
      if (c === '\n') { state = 'code'; out += c; }
    } else if (state === 'block') {
      if (c === '*' && c2 === '/') { state = 'code'; i++; }
      else if (c === '\n') out += c;
    } else {
      // Inside a string/template literal: copy through until the matching quote,
      // honoring backslash escapes so an escaped quote doesn't end it early.
      out += c;
      if (c === '\\') { out += c2 ?? ''; i++; }
      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
        state = 'code';
      }
    }
  }
  return out;
}

// The extensions whose comments `stripComments` actually models. A file outside
// this set is never called comments-only: the parser cannot see its comments, so
// "nothing but comments changed" is a claim it has no grounds for, and answering
// "no" is the end that fails safe for both callers below.
export const COMMENT_CHECKABLE = new Set([
  '.mjs', '.cjs', '.js', '.jsx', '.ts', '.tsx', '.c', '.h', '.cc', '.cpp', '.hpp',
  '.java', '.go', '.swift', '.kt', '.dart', '.rs', '.cs', '.scss', '.css',
]);

// Did a change to `file` touch only its comments? `before`/`after` are the file's
// two contents, null where it was added or deleted — neither of which is a
// comment-only change, whatever the other side holds.
//
// Indentation and blank lines are ignored, so a whitespace-only edit inside a
// template literal reads as comments-only; in a language whose indentation is
// semantic the extension set above has already answered no.
//
// Its callers grant a PERMISSION on the answer — may this run land its own pull
// request unreviewed, may it have touched this file at all — which is why the safe
// end is "no" and why the answer lives here rather than in each of them.
export function commentOnly(file, before, after) {
  if (before == null || after == null) return false;
  const dot = file.lastIndexOf('.');
  const ext = dot === -1 ? '' : file.slice(dot).toLowerCase();
  if (!COMMENT_CHECKABLE.has(ext)) return false;
  const meat = (text) => stripComments(text).split('\n').map((l) => l.trim()).filter((l) => l !== '').join('\n');
  return meat(before) === meat(after);
}

import { basename } from 'node:path';
import { finding } from '../../../../engine/checks/helpers/findings.mjs';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../engine/checks/helpers/code-scanning.mjs';

// The write-surface gate for the improve-comments pass. Its skill bounds every edit
// to comments in code files and to `README.md` documents; the pass runs unattended
// and writes the repo's OWN SOURCE — the one surface no other scheduled task
// touches — so the boundary needs a machine guarantee rather than a prose request.
//
// THE PERMISSION IS READ, NEVER ASSERTED. A file passes because its code is
// identical once the comments are stripped from both sides, not because the run
// says it only touched comments. That is the whole point: a run that quietly
// renamed a variable while "improving comments" is exactly what this catches, and
// a run cannot talk its way past a text comparison.
//
// THREE SHAPES FAIL, and each is deliberate rather than an oversight:
//   - a file whose language `commentOnly` cannot parse counts as code, so a comment
//     edit in one reds the run. Answering "I could not look" as a pass would make
//     the gate silently narrower than the languages a repo actually holds;
//   - an ADDED or DELETED code file is never comment-only, whatever it holds — a
//     whole file is a whole file, and this pass does not add or remove them;
//   - a DELETED `README.md` is not an improvement to a README. Modifying one is the
//     pass's business; deciding a document should not exist is not;
//   - ANY change under `.claudinite/`, comment-only or not. The mount is not the
//     repo's own source: `shared/` is vendored and the next converge replaces it
//     whole (that half is already invisible to every check — repo-context drops
//     the shared prefix), and `.claudinite/local/` is what the growth tasks write.
//     The task's precondition keeps the mount out of a round's scope; this is what
//     holds when a run reaches for one anyway.
//
// RELEVANCE IS THE PINNED COMMIT SUBJECT, the same self-gating shape
// claudinite-growth's capture gate uses: the run marks itself, so this rule can run
// everywhere basics is declared — at the session Stop hook and on every PR — and
// costs ~nothing on a branch that is not this pass.
export const IMPROVE_COMMENTS_RUN = /^Claudinite tidy: improve comments/;

const isReadme = (p) => basename(p).toLowerCase() === 'readme.md';

// The same prefix the task's precondition filters its scope by (MOUNT_PREFIX in
// tasks/improve-comments/task.json); that task imports nothing, so the two are held
// in step by the test beside this check rather than by a shared constant.
const MOUNT_PREFIX = '.claudinite/';
const inMount = (p) => p.startsWith(MOUNT_PREFIX);

const rule = {
  id: 'improve-comments-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/basics/skills/improve-comments/SKILL.md',
  description: 'An improve-comments run changes only comments in code files outside the .claudinite/ mount, and README.md documents',
  why: 'the pass runs unattended against the repo\'s own source, and its whole safety case is that a comment cannot change behaviour — a run that also moved a line has made an unreviewed code change wearing a housekeeping title',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => IMPROVE_COMMENTS_RUN.test(m))) return [];

    const deleted = new Set(work.deleted);
    return [...new Set([...work.changedFiles, ...work.deleted])]
      .filter((p) => inMount(p) || (isReadme(p) ? deleted.has(p) : !commentOnly(p, work.readBase(p), work.read(p))))
      .sort()
      .map((p) => finding(rule, inMount(p)
        ? {
          file: p,
          what: `an improve-comments run changed ${p}, which is inside the ${MOUNT_PREFIX} mount`,
          fix: `revert ${p} — the mount is not this repo's source: the next converge replaces it whole, so a comment improved there is gone by morning; take the change to the canon instead`,
        }
        : isReadme(p)
        ? {
          file: p,
          what: `an improve-comments run deleted ${p} — a README may be improved, never removed`,
          fix: 'restore the file; deciding a document should not exist is a change that gets reviewed, not a comment pass',
        }
        : unparseable(p)
          ? {
            file: p,
            what: `an improve-comments run changed ${p}, whose language the comment parser cannot read`,
            fix: `revert ${p} — outside the parser's set a file counts as code, so nothing here can show the change was only comments; leave them to a change that gets reviewed`,
          }
          : {
            file: p,
            what: work.readBase(p) === null || deleted.has(p)
              ? `an improve-comments run added or deleted ${p}, which is never a comment-only change`
              : `an improve-comments run changed more than the comments in ${p}`,
            fix: 'keep the branch to comment text in code files and to README.md content — a rename, a moved line or a reformat is its own change, with its own review',
          }));
  },
};

// Whether the file's language is one `commentOnly` can parse at all. Only used to
// pick the remedy: a run told "you changed more than comments" about a `.py` file
// it only commented would go looking for a code edit that isn't there.
function unparseable(p) {
  const dot = p.lastIndexOf('.');
  return !COMMENT_CHECKABLE.has(dot === -1 ? '' : p.slice(dot).toLowerCase());
}

export default [rule];

// claudinite-tasks — the whole scheduled-work surface: the queue, the executor, the
// task contract, and the delivery lane a task's output lands through. What the
// mechanism does, and why it is shaped this way, is the canon's own tasks-dispatch design
// document; how it is wired into a repo is this pack's README.
//
// WHY A PACK AND NOT ENGINE CODE. The engine is what every pack's content needs in
// order to EXIST in a repo — discovery, loading, checks, hooks, the mount. Scheduled
// work is not that: a repo that declares no tasks pack runs no scheduled work, and
// that is a supported state rather than a degraded one. Engine membership is decided
// by extending.md's test — would every pack's content stop working without it? — and
// the queue stopped passing it.
//
// WHAT RIDES ALONG. Queue meta-machinery lives here rather than where it historically
// landed, because its subject is this mechanism and nothing else: `task-janitor`
// (the queue's own sweeps, from basics), `usage-fold` (it folds this mechanism's run
// records and outcome labels, from claudinite-growth), and the two task-declaration
// checks (from claudinite-growth). The simulator and its scenario suite — the
// mechanism's executable spec — are in this pack's own test/.
//
// SHARED-CODE IS THE PUBLISHED SURFACE. `shared-code/` is the one place in the corpus
// another pack's code may import across a pack boundary (the `pack-independence`
// barrier's allow list names it, and nothing else). Everything of this pack outside
// it stays off-limits.
//
// SEEDED AT `--init`, NEVER FINGERPRINTED. A new repo gets scheduled work by default —
// the update task is what keeps its Claudinite current, so a member without a queue is
// one nobody is maintaining — and removing the declaration is a durable opt-out.
// Nothing in a repo's SHAPE implies wanting a queue, so there is no
// fingerprint: a scan that suspected one would suspect it everywhere.
//
// Adoption is still a moment a person is present, because it wires two workflow files
// and the routine endpoints a member cannot converge into place.
export default {
  version: '60907.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'scheduled work — the work-item queue, the executor, the task contract and its signals, run records, code-work, delivery',
    excludes: 'authoring a task — claudinite-growth; this repo\'s Claudinite status — claudinite-lifecycle; rendering queue state — claudinite-dashboard',
  },
  seededByDefault: true,
};

// The claudinite-fleet-sheepdog pack: a MARKER + config. Declaring it on a repo makes that repo the
// fleet ENFORCER — the one that covers and maintains every repo under an owner. It's
// opt-in (a dedicated claudinite-fleet-sheepdog repo declares it; NOT seeded by --init).
//
// The pack is thin: prose (RULES.md), the config schema (the pack entry's config =
// { owner, kind, exclude, canonRepo, packSeeds }), and the
// account-spanning sweeps
// that ARE the cross-repo reach the pack adds — each with the ordinary agentless
// scheduled task that runs it (the sweep IS its code-work, and its
// code_work_required_secrets is what asks the repo for FLEET_GITHUB_TOKEN):
//
//   tasks/fleet-roster/check-fleet-roster.mjs          is a repo a MEMBER, and is that
//     adoption-issues.mjs + freshness.mjs               membership still MEANING anything?
//                                                      (one walk, two issue families)
//   tasks/fleet-add-missing-packs/                     which packs is a member MISSING — the
//     scan-for-needed-packs.mjs + force-add-packs.mjs  ones its SHAPE suspects, or the ones
//                                                      the owner named on a forced run?
//   tasks/fleet-pack-seeds/check-fleet-pack-seeds.mjs  does a member DECLARE what
//                                                      this fleet standardizes on?
//   tasks/fleet-baseline/force-fleet-baseline.mjs      make every member baseline NOW
//                                                      (no preconditions — the
//                                                      operator's lever, forced only)
//
// Each sweep lives INSIDE its task's folder — nothing outside that task uses it.
// The pack root holds only what they all need: fleet-api.mjs (the cross-repo REST
// primitives), fleet-config.mjs (the one reader of this pack entry's config) and
// fleet-token.mjs (the one statement of what FLEET_GITHUB_TOKEN must be granted).
//
// ROSTER carries two questions rather than one because they are asked of the same
// repos from the same walk (#788): coverage, and — because per-project scheduling made
// every member maintain itself and in doing so removed the last thing that looked at a
// member from the OUTSIDE — whether that coverage still means anything. Self-maintenance
// cannot detect its own absence. One enumeration, one declaration read per repo; the
// split that remains is between the QUESTIONS (adoption-issues.mjs, freshness.mjs),
// which answer on unrelated conditions, and not between two walks that could classify
// the same repo differently. Only coverage files issues — freshness answers on the run
// report, because the dashboard already carries that fact from the same source (#1854).
//
// ADD-MISSING-PACKS exists because a pack's `detect` fingerprint is consulted ONCE, at
// bootstrap's --init: baselining backfills the seeded packs and each declared pack's
// `requires` closure, but never re-fingerprints, so a member that grows into a pack
// after adoption is never told. It is PARAMETERISED (`scan_for_needed_packs`, `repos`,
// `ADD_PACKS`… — no defaults; the weekly declaration sends its own explicitly, a forced
// run sends the rest through the scheduler's override bag) and it runs NO agent here: it
// converges a work-list issue IN each member and fires that member's own scheduler, whose
// adopt-requested-packs task (claudinite-growth) adopts with the repo checked out —
// the fan-out model (#749): the enforcer dispatches, the member executes, and no agent
// anywhere needs cross-repo access.
//
// PACK-SEEDS is the one that WRITES to members: some packs need a parameter no
// member can derive, because the answer is a fact about the FLEET — and only the enforcer
// holds it, because it IS the fleet. It names no pack itself: every id comes from this
// repo's own `packSeeds`.
//
// The pack carries NO workflow of its own: every sweep runs Action-side inside the
// repo's one scheduler workflow, where the secret is already reachable, and the two
// operator levers (fleet-baseline; a forced fleet-add-missing-packs) are `manual` /
// hand-created work items on that same queue — `create-work-item <pack>/<task>`. The
// standalone fleet-baseline workflow this pack once kept in the enforcer's .github/
// (the one file the nightly converge could never push itself, #649) was retired
// 2026-08-11 (#749, packs/claudinite-fleet-sheepdog/migrations/2026-08-11-fleet-baseline-task) along with its
// follow-the-fleet report: dispatching is the enforcer's job, reporting is each
// member's own.
//
// Everything else — the scheduler run, the executor, the task engine (packs/claudinite-tasks/),
// scheduling — is CORE and pack-agnostic; none of it runs, dispatches, or depends on
// these sweeps.
//
// ONE CHECK, and it names no pack (seeds-agree.mjs): the seed sweep writes this
// repo's `packSeeds` into every member without ever consulting what this repo declares
// for the same pack, so the two can drift apart silently. That is a fact about seeding,
// not about any pack seeded — which is why it lives here and not in the pack whose
// config happened to drift.
import { fleetTokenHandoverStep } from './fleet-token.mjs';

export default {
  version: '60907.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'fleet-enforcer duties for the repo watching every other repo — coverage, freshness, standardized packs',
    excludes: 'anything a member does to itself — its comments are basics, lessons are claudinite-growth; the fleet brief is claudinite-dashboard',
  },
  // Every sweep here runs as a task on the enforcer's own queue, and each one asks
  // whether a member's SCHEDULER is dormant — a question the tasks pack owns and
  // publishes (shared-code/dormancy.mjs). Declared so the vendor set carries the code
  // this pack imports: an enforcer that mounted the sweeps without it would fail its
  // own converge on a dangling import.
  requires: ['claudinite-tasks'],
  // Audits the enforcer's config as it stands, whatever this session touched: a seed
  // that drifted in an earlier commit is just as silent as one that drifted in this one.

  // The token is the whole pack's one credential and only a human can mint it. The step
  // is RENDERED from fleet-token.mjs rather than written here, because the failure this
  // exists to prevent is a person granting a subset (#1030): a sweep's own message names
  // what that sweep needs, and five such messages assemble into a grant missing exactly
  // the permission no other sweep exercises. What adoption presents is the union.
  adoptionHandover: [fleetTokenHandoverStep()],
};

// claudinite-dashboard — a browser view of what a repo's (or a fleet's) Claudinite
// scheduler is doing, published as a static site.
//
// WHY A PACK AND NOT ENGINE CODE. The dashboard is not part of running the scheduler:
// nothing converges, scheduler runs or executes because it exists, and a member that never
// looks at it should not carry it. Engine code is what every member runs; this is
// content a member OPTS INTO, and adoptable content in this corpus is a pack. That
// also buys it the things a pack has and engine code does not — its own version and
// migration lane, a declaration that gates it, and an adoption moment at which its
// deployment can be wired.
//
// WHAT IT READS. Only the queue's own vocabulary and the task declarations at HEAD,
// through the tasks pack's published `shared-code/`, so the page cannot drift from the
// mechanism it renders. Those relative paths resolve identically in the canon (`packs/<id>/`
// beside its siblings) and in a member's mount (`.claudinite/shared/packs/<id>/`), which is
// why the pack can be read straight out of the mount with nothing rewritten.
//
// NO PROSE. There is no way to write the dashboard wrongly in a consuming repo — it is
// a page, not a practice — and prose here would cost every session in every declaring
// repo tokens for something no session acts on. Its README carries the explanation
// instead and `prose` stays null.
//
// PACKS CONTRIBUTE TO THIS PAGE, as data and never as code. A pack ships a descriptor
// (`packs/<id>/dashboard.json`, found by path convention — nothing registers it) naming
// what it has to say; its values come either from its own generated file in the
// member's tree or from one of the two platform facts the page already reads for every
// member. `descriptor-usable`, this pack's one check, holds a descriptor to what the
// page's OWN reader accepts, which the JSON Schema beside it structurally cannot,
// because the failure is silent — a rejected descriptor renders as one apologetic line
// in someone else's browser and nothing goes red where the author is looking.
//
// PUBLISHING IS A TASK, AND A FOUR-STEP WORKFLOW. `.github/workflows/` is the one
// directory the nightly update can never push to (the Action's `GITHUB_TOKEN` is
// refused there), so whatever the deploy keeps there is frozen at adoption. It keeps
// the least it can: a Pages deploy with source "GitHub Actions" is marketplace actions
// that only workflow YAML can invoke, so the seeded workflow (`seedOps`, below) holds
// exactly those — checkout of `gh-pages`, configure, upload, deploy — and nothing that
// could ever need to change. The `publish-pages` task owns the rest: when to run, the
// build, the push of the built tree to `gh-pages`, the dispatch, the follow-through.
// What adoption cannot do is enable Pages — the handover step below.

export default {
  version: '60907.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'the browser dashboard over Claudinite scheduler state and the site that publishes it',
    excludes: 'how the scheduler behaves — core; workflow practice — git-github; product sites — static-website',
  },

  // Never fingerprinted. Nothing in a repo's shape implies wanting a dashboard, and a
  // scan that suspected one from the presence of a scheduler would suspect it in every
  // member on the fleet.
  seededByDefault: false,

  // The page renders the queue's state, so it reads the queue's own vocabulary and
  // anchor math out of the tasks pack's published `shared-code/` — the one sanctioned
  // cross-pack import in the corpus. Declaring the dependency is what puts that pack
  // in a mount that carries this one.
  requires: ['claudinite-tasks'],

  // A page, not a practice — see the header.

  // ONE question, and it is the one thing this pack cannot pick for a repo: which
  // dashboard the deployment is. Everything else has a default that is right for nearly
  // every project — a pasted token, no canon reference — and is read
  // as optional throughout, an unset key meaning the default rather than a
  // misconfiguration. The mode is not like that: both answers are ordinary, neither is
  // rarer, and guessing it wrong publishes a plausible-looking site covering the wrong
  // thing. So it is asked, and the build refuses to publish without it.
  //
  // config keys — `mode` is REQUIRED, the rest optional:
  //   mode        — "repo" (this repo's own page) or "fleet" (the overview); no default
  //   canonRepo   — the reference member mounts are compared against (fleet view)
  //   rosterUrl   — a roster artifact; more than one member makes the fleet the landing view
  //   repos       — an inline roster instead of a URL
  //   allowedOrigins — page origins allowed to call the exchange endpoint (defaults to
  //                    the redirectUri's origin, then to this owner's Pages host)
  //   workerName  — what the deployed endpoint is called (defaults per the task)
  //
  // The sign-in pair are REPOSITORY VARIABLES rather than config, since they are what an
  // owner sets while standing in the GitHub App's settings and the second is minted by a
  // deploy rather than authored — `CLAUDINITE_DASHBOARD_CLIENT_ID` and
  // `CLAUDINITE_DASHBOARD_EXCHANGE_URL`, both read by `deployment-config.mjs`. A
  // `clientId`/`exchangeUrl` still on a declaration is read as the fallback, so a
  // deployment configured before they existed keeps its button; the build says so once.
  //   owner       — whose repos the fleet view enumerates (defaults to this repo's owner)
  //   exclude     — repos it keeps out (defaults to none)
  questions: [
    {
      id: 'mode',
      prompt: 'Is this deployment this repo\'s OWN dashboard, or the fleet overview across many repos? A fleet deployment also needs to name where its members come from — an "owner" whose repos are enumerated in the browser as the viewer (the one to prefer), or an explicit "repos" list or roster artifact.',
      distill: 'set config.mode to "repo" or "fleet" — there is no default and the build refuses to publish without it; a "fleet" answer must come with a roster source (owner/repos/rosterUrl), and a "repo" answer with none',
    },
  ],

  // The one step adoption CANNOT take, stated where the install flow can print it and
  // the adopting session can file it. Enabling Pages is a repository setting, and
  // `actions/configure-pages`' own `enablement` input cannot do it with the Action's
  // `GITHUB_TOKEN` — it needs a PAT with `repo`, or an app with `administration:write`.
  // Holding a credential that wide, in every member, to save one click is a far worse
  // trade than naming the click. So it is named.
  //
  // In a README this would be met after the first publish had already parked; here it
  // arrives at the moment someone is present and the pack is new.
  adoptionHandover: [
    {
      step: 'Enable GitHub Pages with source "GitHub Actions" — this repo\'s /settings/pages',
      breaks: 'the publish-pages task pushes the build, and its deploy run then fails — the task parks at needs-human-action naming this',
      done: 'the Pages URL serves the dashboard, and a publish-pages run converged done',
    },
    // ONE entry, not the four mechanical steps, because for many deployments the right
    // answer is "nothing" — a member's own dashboard read with a pasted token is on the
    // same 5,000/hour as a signed-in one. What every adopter does have to meet is the
    // DECISION, since until someone makes it their page reads GitHub anonymously; four
    // unconditional checkboxes that are mostly no-ops teach the reader to skim exactly
    // the list that exists to stop them skimming. The mechanics live in the README,
    // where they are read at the moment the answer is yes — and a `step` becomes one
    // checkbox in somebody's handover issue, so spelling them here would put six
    // actions and a rationale inside one box (basics' `writing-handover-issues`).
    {
      step: 'Decide how this dashboard authenticates its viewers: leave it on the pasted-token box, or turn on '
        + 'Sign in with GitHub — the pack README\'s "Turning sign-in on" is that checklist.',
      breaks: 'nothing fails, but a viewer who has not pasted a token reads GitHub anonymously at 60 requests/hour per IP — '
        + 'which one fleet sweep exceeds, so the page serves cached data or empty rows until the hour rolls',
      done: 'a signed-in viewer sees the rate pill read “…/5000 · user”, or this repo has recorded that the token box is '
        + 'this deployment\'s answer',
    },
  ],

  // Seeded, never converged: `.github/workflows/` cannot be written by the nightly, so
  // this arrives once, at adoption, and the repo owns it from there. Only `uses:` steps,
  // for exactly that reason — the part that cannot be updated holds nothing to update.
  seedOps: [
    {
      template: 'stubs/workflows/claudinite-dashboard-pages.yml',
      dest: '.github/workflows/claudinite-dashboard-pages.yml',
    },
  ],
};

// Opt into the growth lifecycle: a repo declaring claudinite-growth contributes its
// hard-won lessons up to the Claudinite canon and prunes them back out once the canon
// owns them. This pack carries the REPO-side stages — extract, dedup, and the weekly
// prose-to-checks sweep — as scheduled tasks under this pack's
// own `tasks/`, discovered by the scheduler's filesystem scan
// (packs/claudinite-tasks/discover.mjs), so none of them is declared here. The central
// promote stage — lifting portable lessons up into the shared canon — is a home-only
// duty that runs canon-side, outside this pack; its precondition targets exactly the
// members that declare THIS pack, minus any member whose entry sets config.promote:
// false (the promotion opt-out; extraction and dedup stay local either way).
//
// EXTRACTION IS ONE TASK OVER TWO SOURCES. growth-extract (tasks/growth-extract/)
// runs the extract-from-activity skill over the window's commits/PRs/issues and the
// extract-from-conversations skill over the captured logs, then the prose-to-checks
// skill over the prose it just wrote, and lands all of it in one PR delivered
// per the repo's delivery settings.
// The halves were two tasks firing at the same nightly anchor against the same local
// packs; they shared the bar, the ladder and the dedup surface, so the split bought
// nothing and cost a second opus dispatch, a second PR, and two runs deduping
// against a corpus the other was concurrently writing.
//
// The pack also owns the CONVERSATION lifecycle: capture-log.mjs pushes a session's
// conversation onto the orphan conversation-logs branch (in-session — it needs the
// live transcript), driven by TWO events: merge-to-main's capture step, with the
// issue the merge closed, and session-end.mjs, with --issue 0, invoked by the
// engine's SessionEnd hook runner. The second is best-effort and captures what the
// first structurally cannot — sessions that never merge, and the post-merge tail of
// the ones that do; it is safe to double-write because capture deltas on the session
// id. growth-extract's conversation half then mines those pushed logs on its own
// access model — the logs branch is in the repo, so reading it, committing lessons to
// local packs are plain local git (the logs branch itself is read-only to it); only
// posting the short summary behind each extracted rule on its issue uses the GitHub
// MCP tools. RETENTION IS A SEPARATE, AGENTLESS TASK (tasks/logs-prune/): deleting a
// capture past config.retention_days is arithmetic on dates, and keeping it inside
// the opus run also kept a precondition arm alive whose only job was to dispatch
// that run on a quiet repo. Age is enough because of the extract run's reading
// window — it reads from the oldest end of the branch every run — not because the
// two tasks hand anything to each other.
//
// And it owns the SKILL-USAGE metric the promotion ladder's skill-vs-prose call was
// missing: usage-fold (tasks/usage-fold/) counts skill loads and their activity
// denominators out of those same captured logs into a small tracked aggregate.
// Fleet-wide aggregation is NOT here — the canon knows mechanisms, never repos; that
// is the claudinite-fleet-sheepdog pack's job, in the fleet-enforcer repo.
//
// ADOPTION IS NOT HERE. `adopt-claudinite`, `adopt-pack` and the
// adopt-requested-packs task were bundled in this pack for want of a better home;
// their subject is Claudinite's own surface, so they moved to the `core` pack.
//
// rule-revalidation (tasks/rule-revalidation/) covers the failure mode the other
// stages structurally cannot see: a rule that was right, and whose ENVIRONMENT
// moved. A claim about the harness, a token's reach or an MCP tool's existence is
// falsified by a platform this repo does not control, and nothing here goes red
// when it happens — so the trigger is the calendar, and the method is re-running
// the probe rather than re-reading the prose. It shares prose-to-checks-sweep's
// `pack_paths` config: a member revalidates its own local packs, the canon its own.
//
// A declared pack (no fingerprint), seeded like the baseline: --init seeds it into every
// new repo, the one-time grow-with-claudinite-seed migration seeds the existing fleet,
// and baselining never re-adds it — so removing it is a durable opt-out.
//
// No adoption question over config.retention_days — the task carries the default
// (DEFAULT_RETENTION_DAYS, in tasks/logs-prune/prune-logs.mjs) rather than something
// every adopter must weigh in on, and a project overrides it by declaring the value.
// The default is what "unset = capture-only" turned out to need: absence read as
// fail-safe and behaved as an unbounded leak, since no adoption flow asked for the
// value and nothing seeded it (#1620). Capture-only is now declared, not inferred.
export default {
  version: '60907.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'authoring Claudinite content here — lesson extraction, dedup, revalidation, conversation logs, skill-usage folding, the task contract',
    excludes: 'this repo\'s Claudinite status — mount, declaration, adoption, update — claudinite-lifecycle; code comments — basics; fleet sweeps — claudinite-fleet-sheepdog',
  },
  seededByDefault: true,
  // Growth builds on Claudinite's own surface — a lesson is routed by reading the
  // pack catalog and landed by adopting or authoring a pack — so `core` is a
  // prerequisite rather than an ambient assumption.
  requires: ['claudinite-lifecycle'],
  // The task contract (the writing-tasks skill). Relevance-first — inert until
  // the repo carries a tasks/<name>/task.json of its own — and here rather than in
  // claudinite-lifecycle because these judge whether a task is WRITTEN correctly,
  // which is authoring, not whether Claudinite is working in this repo. The
  // contract's third rule (task-phase-discipline) is a declared check in this pack's
  // declared-checks.json, beside them.
};

  if (!files.length) return set;
  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
    { allowFail: true, input: files.join('\n') + '\n' });
  for (const line of (out || '').split('\n')) {
    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
    if (m && m[2] === 'set') set.add(m[1]);
  }
  return set;
}

// The complete set of top-level settings the settings file may carry. A key
// outside this set is a typo or a stale name — a settings error as real as invalid
// JSON, caught at load so it can't silently change nothing. `packConfig` is the
// legacy home of per-pack parameters — still honored while the fleet migrates to
// pack-entry `config` (the converge folds it in), no longer documented. The
// `pack-entry-config` baseline migration (engine/migrations/) documents the fold; the
// key and the overlay below come out on #1640's window, after which a straggler gets
// the unknown-setting error.
// `engineVersion` is the engine version this repo's mount holds, written by the
// update flows; a pack's installed version sits on that pack's own entry. Both were
// a nested `claudinite` block until #1252, alongside an `updated` datetime and a
// `ref` — those two held the provenance of the last FULL re-vendor rather than of
// this mount, so a member converging nightly read as months stale, and nothing may
// judge freshness by them any more because they no longer exist.
// `dailyClaudiniteUpdatesRequirePrReview` is the harsh override: true leaves this
// repo's daily update PR open for a human. Absent — the normal shape — means it
// lands on its own. It is an override rather than a materialized preference
// because every member wants the same thing, and the one that doesn't should have
// to say so (#1252).
// `taskScheduler` is the per-repo maintenance anchor the vendored hourly scheduler
// reads (per-project-scheduling DESIGN §2) — { dailyHour, weeklyDay, monthlyDay },
// all UTC. Absence means the documented defaults, so an omitted key is not an
// error; a present one is range-validated at load below. Its declaration is also
// the per-repo cutover marker during the scheduling rollout (MIGRATION Phase 0.6).
// Nothing writes into a member's README any more, so there is no `badges` key here:
// a member carrying the stale one gets the unknown-setting error below, and the
// wiring converge clears it.
// There is no `dormant` key either. Dormancy is a property of the SCHEDULER, not of
// the repository — every effect it has is an effect on the work-item queue — so it is
// a parameter of the pack that owns that mechanism, declared on that pack's own entry,
// and the engine neither validates it nor normalizes it. A repo declaring no scheduler
// pack has none for the word to mean anything about.
// `claudinite` and `maintenance` are the two retired blocks, tolerated on read so a
// member that has not yet run the #1252 record still loads. LEGACY_CONFIG_KEYS is
// what Phase 3 deletes.
export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants', 'packConfig',
  'engineVersion', 'dailyClaudiniteUpdatesRequirePrReview', 'taskScheduler'];

// Keys accepted on the way in and written by nothing. The first two are the retired
// BLOCKS, whose content is folded into the current shape by the load below so nothing
// downstream sees either name. `dormant` is here for a different reason: it was never
// the engine's to fold, and its reader lives in the pack that owns the scheduler. It is
// listed only so a member still declaring it at the top level collects no
// unknown-setting error while the migration record converges the fleet onto the pack
// entry — which is why it retires on its own issue rather than with the blocks.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
export const LEGACY_CONFIG_KEYS = [
  'claudinite', 'maintenance',
  // @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
  'dormant',
];
const KNOWN_CONFIG_KEYS = [...CONFIG_KEYS, ...LEGACY_CONFIG_KEYS];

// The predicate this module used to own, kept ONLY for the pack-lane window. The engine
// and a pack reach a member on separate cycles, so every member spends a window holding
// this engine beside a pack version that still imports `isDormant` from here — and a
// missing export there is a crash mid-converge, in the flow that would have delivered
// the fix.
//
// It reads the retired top-level key and nothing else, which is exactly right for the
// callers it exists for: a pack old enough to import it is old enough to predate the
// pack-entry spelling, so this answers the only question that code knows how to ask.
// It is NOT the definition — that is the tasks pack's, which resolves both spellings —
// and nothing new may call it.
//
// @deprecated Use the `isDormant` the scheduler's own pack publishes from its
// shared-code surface, which is where the live definition lives.
// @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
export const isDormant = (config) => config?.dormant === true;

// The keys a `schedule` object may carry, and the canonical weekday vocabulary
// (mirrored from the scheduler's own WEEKDAYS — kept as a literal here so the checks
// layer does not import the scheduler).
const SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay', 'dispatch', 'agenticTaskInvocationEndpoints', 'endpoints', 'disabledTasks'];

// Is this project's SCHEDULER dormant? A project goes dormant when it is finished,
// parked, or simply not being worked on: it should stop paying the upkeep of a project
// that IS being worked on.
//
// WHY THIS LIVES IN THIS PACK. Every effect dormancy has is an effect on the queue —
// nothing is instantiated, nothing is picked up, and nothing outside expects movement.
// A repo that declares no tasks pack has no scheduler at all, so the word means nothing
// there, and an engine that validated it for such a repo was answering for a mechanism
// it does not own. So the setting is one of this pack's parameters, declared where the
// pack is:
//
//   { "id": "claudinite-tasks", "config": { "dormant": true } }
//
// What dormancy means, exactly — it is narrow on purpose:
//   - NO RECURRING WORK. The vendored scheduler stops before it evaluates a
//     precondition, so no work item is instantiated, no agent session is started, and
//     no maintenance PR is opened. Nothing scheduled runs "for nothing" on a repo
//     nobody is working on.
//   - NO SCHEDULER CEREMONY FROM OUTSIDE. Whatever looks at this repo from the outside
//     reads the same declaration and does not report a stopped scheduler as unhealthy —
//     a scheduler TOLD to stop must not then be nagged for stopping. It says nothing
//     about the repo's other health: a dormant member whose mount has fallen behind
//     canon is still behind, and is still reported as behind.
//   - EVERYTHING ELSE STAYS ON. Claudinite is not switched off: the session hooks, the
//     checks engine, the mounted skills and pack prose all work exactly as before the
//     moment someone opens a session on the repo. Dormancy is about unattended upkeep,
//     never about what an interactive session may do.
//
// ONE PREDICATE, EVERY SHAPE. It reads a raw parsed .claudinite-settings.json and the
// normalized config `loadConfig` returns, because a cross-repo reader fetches another
// repo's declaration over the API with no engine loaded against that tree and must
// decide dormancy by the same test that repo's own scheduler used. A second notion of
// dormancy would nag exactly the repos that had already opted out.
//
// Import-light and free of `node:` on purpose: the dashboard page reads this in the
// browser through the pack's published shared-code/, and a `node:` import anywhere in
// that graph blocks the page's first module load.
import { RENAMED_PACKS } from '../../engine/pack_loader/renamed-packs.mjs';

// Whose parameter this is. Exported because a reader that has to name the pack to find
// its config should name it from here rather than spell the id a second time.
export const TASKS_PACK_ID = 'claudinite-tasks';

// A declared id as it resolves today. A member's declaration can carry a spelling from
// before a rename, and the config of a pack a member writes into its own repo must keep
// resolving under every spelling it was ever written under.
const resolves = (id) => typeof id === 'string' && (RENAMED_PACKS[id] ?? id) === TASKS_PACK_ID;

// This pack's parameters, from whichever shape the caller holds.
//
// The normalized view first: `loadConfig` folds every entry's `config` into `packConfig`
// keyed by the pack's own id, so a scheduler that already loaded its settings needs no
// second walk. Then the raw declaration, where the parameters sit on the entry object as
// the member wrote them — which is all a cross-repo reader ever has.
function packParameters(config) {
  if (config === null || typeof config !== 'object') return undefined;
  const folded = config.packConfig?.[TASKS_PACK_ID];
  if (folded !== null && typeof folded === 'object') return folded;
  for (const entry of Array.isArray(config.packs) ? config.packs : []) {
    if (entry !== null && typeof entry === 'object' && resolves(entry.id)) return entry.config;
  }
  return undefined;
}

// What the declaration says, before any judgement about whether it says it legally.
// `undefined` means the project never answered, which is the normal shape and means awake.
function declared(config) {
  if (config === null || typeof config !== 'object') return undefined;
  const own = packParameters(config)?.dormant;
  if (own !== undefined) return own;
  // The retired spelling, underneath the pack entry so a converged member is never
  // overridden by a stale key its migration left behind. `raw` is the declaration as
  // the member wrote it, which is where a top-level key survives now that the engine
  // no longer normalizes one it does not own.
  // @legacy-tolerance advisory:legacy-shape-in-use retire:#1846
  return config.raw?.dormant ?? config.dormant;
}

// The predicate. Strictly `=== true`, so every malformed value below reads as awake —
// the conservative direction, since the alternative is silently stopping a project's
// entire scheduled workload on a typo.
export const isDormant = (config) => declared(config) === true;

// The settings errors this parameter can carry, in the `{ what, fix }` shape the world
// runner collects. A string "true", a `{ since }` object or a reason left in its place
// would all read as dormant to a truthiness test and as awake to the predicate above,
// and the difference is a whole repo's scheduled work — so the wrong TYPE is reported
// rather than coerced. The pack owns this because the pack owns the parameter.
export function dormancyErrors(config) {
  const value = declared(config);
  if (value === undefined || typeof value === 'boolean') return [];
  return [{
    what: `"dormant" on the "${TASKS_PACK_ID}" pack entry must be true or false, got ${JSON.stringify(value)}`,
    fix: `set it to true to stop this project's recurring work, or remove it — e.g. { "id": "${TASKS_PACK_ID}", "config": { "dormant": true } }`,
  }];
}

