92	// that did not move.) Kept free of I/O so every branch is testable directly.
93	export function classifyScope(r, { canonRepo, exclude, filter }) {
94	  const fullName = r.full_name.toLowerCase();
95	  if (fullName === canonRepo.toLowerCase()) {
96	    return { state: 'canon', detail: 'canon has no vendored mount — forcing it would queue a run whose only outcome is its own self-skip' };
97	  }
98	  if (r.archived || r.fork) return { state: 'out-of-scope', detail: r.archived ? 'archived' : 'a fork' };
99	  if (exclude.has(fullName)) return { state: 'excluded', detail: "on the claudinite-fleet-sheepdog config's exclude list" };
100	  if (filter && !filter.has(fullName)) return { state: 'filtered-out', detail: "not in this run's REPOS filter" };
101	  return null;
102	}
103	
104	// --- main ---------------------------------------------------------------------
105	
106	export async function main() {
107	  const token = process.env.FLEET_GITHUB_TOKEN;
108	  const home = process.env.GITHUB_REPOSITORY;
109	  if (!token) {
110	    throw missingFleetTokenError('fleet-baseline',
111	      'The default GITHUB_TOKEN sees only this repo and cannot dispatch another repo\'s workflow.');
112	  }
113	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
114	  const gh = makeGh(token);
115	
116	  const dryRun = String(process.env.FLEET_BASELINE_DRY_RUN ?? '').toLowerCase() === 'true';
117	  const includeDormant = String(process.env.FLEET_BASELINE_INCLUDE_DORMANT ?? '').toLowerCase() === 'true';
118	
119	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
120	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
121	    throw new Error(`the claudinite-fleet-sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
122	  }
123	  let cfg;
124	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
125	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
126	  }
127	  const { owner, exclude, canonRepo } = parseSheepdogConfig(cfg, home);
128	  const filter = parseRepoFilter(process.env.FLEET_BASELINE_REPOS, owner);
129	  // One reader for the whole sweep: it memoizes canon's engine version and each
130	  // pack's, so canon is read once per distinct pack rather than once per member.
131	  const canon = canonVersions(gh, canonRepo);
132	  const followMinutes = Number(process.env.FLEET_BASELINE_FOLLOW_MINUTES) || DEFAULT_FOLLOW_MINUTES;
133	
134	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
135	    .filter((r) => r.owner.login.toLowerCase() === owner);
136	  if (mine.length === 0) {
137	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope`);
138	  }
139	
140	  const fired = []; const skipped = []; const failed = [];
141	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
142	    const fullName = r.full_name.toLowerCase();
143	    // Out of scope before the declaration is read — canon, archived, a fork, excluded,
144	    // or filtered out. classifyScope says why, and each lands in the skipped list: no
145	    // repo leaves this report silently, whatever its state.
146	    const scope = classifyScope(r, { canonRepo, exclude, filter });
147	    if (scope) { skipped.push({ fullName, ...scope }); continue; }
148	
149	    let decl;
150	    try {
151	      decl = await readDeclaration(gh, r.full_name);
152	    } catch (e) {
153	      // Unreadable is not uncovered: a repo whose declaration could not be read might be
154	      // a member that needed this run, so it is a FAILURE to escalate, never a silent skip.
155	      failed.push({ fullName, state: 'error', detail: `could not read ${DECLARATION}: ${e.message}` });
156	      continue;
157	    }
158	    if (decl === null) {
159	      skipped.push({ fullName, state: 'uncovered', detail: `no tracked ${DECLARATION} — adoption is the census's business, and there is nothing there to baseline` });
160	      continue;
161	    }
162	    if (isDormant(decl) && !includeDormant) {
163	      // NOT a second authority on dormancy — `isDormant` here IS the member's own
164	      // scheduler's predicate, re-exported (fleet-api.mjs), so this gate and the gate
165	      // that member's run would apply cannot disagree. What it saves is the dispatch:
166	      // fired anyway, the run would start, read its own declaration, decline and cost
167	      // an Actions minute on a repo that asked for none — the recurring work dormancy
168	      // exists to stop, spent to learn what the declaration in hand already said.
169	      //
170	      // It is also what keeps INCLUDE_DORMANT meaningful. The member's own gate stops a
171	      // woken run too, so an operator override CANNOT be expressed downstream of it:
172	      // without this filter, INCLUDE_DORMANT=true would dispatch to every dormant member
173	      // and every one of those runs would self-skip, reporting `fired` for work that
174	      // never happened. Reported rather than silently dropped, so a fleet-wide force is
175	      // never mistaken for fleet-wide coverage.
176	      skipped.push({ fullName, state: 'dormant', detail: 'self-declared dormant — pass INCLUDE_DORMANT=true to force it anyway' });
177	      continue;
178	    }
179	
180	    if (dryRun) {
181	      fired.push({ fullName, state: 'would-fire', detail: `would dispatch ${SCHEDULER}@${r.default_branch} to wake ${FORCED_TASK}` });
182	      continue;
183	    }
184	    // BEFORE firing, not after: a member already at canon's versions declines its own
185	    // update and never does any work, and only a reading taken before the dispatch can
186	    // tell that success apart from a member that converged because of it. The
187	    // declaration is already in hand, so this costs the mount probe alone.
188	    let wasFresh = false;
189	    try {
190	      wasFresh = classifyFreshness(await probeMount(gh, r.full_name, decl, { canon })).state === FRESH;
191	    } catch {
192	      // Unreadable here is not a failure to dispatch. It only means this member's
193	      // success will be reported as `converged` rather than `already-current`, which
194	      // is the conservative way round: it claims no more than was observed.
195	      wasFresh = false;
196	    }
197	    const firedAt = new Date().toISOString();
198	    const verdict = await fireScheduler(gh, r.full_name, r.default_branch, FORCED_TASK);
199	    if (verdict.state !== 'fired') { failed.push({ fullName, ...verdict }); continue; }
200	    fired.push({ fullName, ...verdict, firedAt, wasFresh });
201	  }
202	
203	  // THE FOLLOW. Everything above queued runs; this is what turns that into an answer
204	  // about the FLEET. Skipped for a dry run, which dispatched nothing and therefore has
205	  // no outcome to wait for.
206	  const followed = dryRun || fired.length === 0 ? [] : await followToCurrent(gh, fired, {
207	    canon,
208	    readDeclaration,
209	    budgetMs: followMinutes * 60_000,
210	    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
211	    log: (line) => console.log(line),
212	  });
213	
214	  const summary = renderBaselineReport({ owner, dryRun, filter, fired, followed, skipped, failed });
215	  console.log(summary);
216	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
217	
218	  const problem = runVerdict({ fired, followed, failed });
219	  if (problem) throw new Error(problem);
220	}
221	
222	const runsUrl = (n) => `https://github.com/${n}/actions/workflows/${SCHEDULER}`;
223	
224	// Each outcome gets its own section, because each is a different thing for the reader
225	// to do — and because collapsing `already-current` into the successes without naming
226	// it would hide the single most useful fact a run can report: that a member needed
227	// nothing. Ordered as the reader wants them: what moved, what was fine, then what to
228	// go and fix.
229	export const OUTCOME_SECTIONS = [
230	  [CONVERGED, 'Converged during this run', 'was behind canon and is now at its versions'],
231	  [ALREADY_CURRENT, 'Already current', "was at canon's versions before the dispatch, so its own update correctly declined"],
232	  [DID_NOT_CONVERGE, 'Started but did not reach canon', 'its scheduler ran — go and read it'],
233	  [NEVER_STARTED, 'Never started', 'the dispatch was accepted and no run followed it'],
234	  [UNKNOWN, 'Could not be determined', 'the member could not be read'],
235	];
236	
237	// The whole report, pure over what the sweep observed — so what it CLAIMS is testable
238	// without a fleet. The headline count is `current of dispatched`, never a count of
239	// dispatches: a table whose big number is "13 fired" is the thing #1292 caught.
240	export function renderBaselineReport({ owner, dryRun, filter, fired, followed, skipped, failed }) {
241	  const current = followed.filter((f) => isSuccess(f.outcome));
242	  const notCurrent = followed.filter((f) => !isSuccess(f.outcome));
243	  const section = ([state, heading, gloss]) => {
244	    const rows = followed.filter((f) => f.outcome === state);
245	    return rows.length
246	      ? `**${heading}** — ${gloss}:\n${rows.map((f) => `- [\`${f.fullName}\`](${runsUrl(f.fullName)}) — ${f.detail}`).join('\n')}`
247	      : '';
248	  };
249	
250	  return [
251	    `# Fleet baseline — ${owner}${dryRun ? ' (DRY RUN — nothing was dispatched)' : ''}`,
252	    '',
253	    dryRun
254	      ? `Would ask each covered member's own \`${SCHEDULER}\` to wake its \`${FORCED_TASK}\` item.`
255	      : `Asked each covered member's own \`${SCHEDULER}\` to wake its \`${FORCED_TASK}\` item, then followed each`
256	        + ` one until its own \`${DECLARATION}\` stamped the engine and every declared pack at the versions canon publishes.`,
257	    filter ? `Filtered to: ${[...filter].join(', ')}` : '',
258	    '',
259	    dryRun
260	      ? `| would fire | skipped |\n| --- | --- |\n| ${fired.length} | ${skipped.length} |`
261	      : `| current | not current | not dispatched | skipped |\n| --- | --- | --- | --- |\n`
262	        + `| ${current.length} of ${fired.length} | ${notCurrent.length} | ${failed.length} | ${skipped.length} |`,
263	    '',
264	    dryRun && fired.length
265	      ? `**Would fire:**\n${fired.map((f) => `- [\`${f.fullName}\`](${runsUrl(f.fullName)})`).join('\n')}`
266	      : '',
267	    !dryRun && !fired.length && !failed.length
268	      ? '**No member was dispatched** — check the filter, or whether anything under this owner is covered.'
269	      : '',
270	    ...OUTCOME_SECTIONS.map(section),
271	    skipped.length ? `**Skipped:**\n${skipped.map((s) => `- \`${s.fullName}\` — **${s.state}**: ${s.detail}`).join('\n')}` : '',
272	    failed.length ? `**Could not be dispatched:**\n${failed.map((f) => `- \`${f.fullName}\` — **${f.state}**: ${f.detail}`).join('\n')}` : '',
273	    '',
274	    // Said plainly rather than left to inference: "current" is a statement about
275	    // PUBLISHED VERSION NUMBERS. Canon content that shipped without a version bump
276	    // moves no number, so a member can read current and still lack it (#1292).
277	    "_Current means the member stamps canon's published engine and pack versions. Canon content_",
278	    '_that shipped without a version bump moves no number, so it is invisible here._',
279	  ].filter(Boolean).join('\n');
280	}
281	
282	// What fails the run, in the order a reader should act on it — or null when the fleet
283	// is current. A dispatch that never landed is a grant or an adoption to fix. A member
284	// that WAS dispatched and is still not current is the failure this whole follow exists
285	// to surface: the one the old report counted as a success. Everything observed is
286	// printed before this is consulted, so a throw ends the run without withdrawing the
287	// report. Pure, so the escalation policy is testable without a fleet.
288	export function runVerdict({ fired, followed, failed }) {
289	  if (failed.length) {
290	    return `${failed.length} member(s) could not be dispatched (${failed.map((f) => `${f.fullName}: ${f.state}`).join('; ')}) — `
291	      + 'the rest are reported above, and this run fails so the cause is escalated';
292	  }
293	  const notCurrent = followed.filter((f) => !isSuccess(f.outcome));
294	  if (notCurrent.length) {
295	    return `${notCurrent.length} of ${fired.length} dispatched member(s) did not reach canon's versions `
296	      + `(${notCurrent.map((f) => `${f.fullName}: ${f.outcome}`).join('; ')}) — `
297	      + 'reported above, and this run fails rather than counting the dispatch as the outcome';
298	  }
299	  return null;
300	}
301	
302	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
303	if (isMain) {
304	  main().catch((e) => { console.error(`fleet-baseline failed: ${e.message}`); process.exit(1); });
305	}
