export function parseRepoFilter(raw, owner) {
  const names = String(raw ?? '').split(/\s+/).map((s) => s.trim()).filter(Boolean);
  if (!names.length) return null;
  return new Set(names.map((n) => (n.includes('/') ? n : `${owner}/${n}`).toLowerCase()));
