1	#!/usr/bin/env node
2	// The claudinite-fleet-sheepdog pack's fleet ROSTER sweep — one walk of the fleet answering the
3	// enforcer's two standing questions about every repo under the owner:
4	//
5	//   is this repo a MEMBER?           → `fleet-adoption` issues   (adoption-issues.mjs)
6	//   is that membership still MEANING anything?
7	//                                    → the report's freshness section (freshness.mjs)
8	//
9	// Run by this pack's `fleet-roster` scheduled task, whose worker calls `main()` below
10	// as the task's `code_work` — Action-side inside the enforcer repo's scheduler workflow,
11	// where the FLEET_GITHUB_TOKEN the task declares in `code_work_required_secrets` is reachable as
12	// ordinary environment. Still runnable by hand (`node check-fleet-roster.mjs`) via the
13	// CLI guard at the foot.
14	//
15	// WHY ONE WALK (#788). The two questions were two tasks, and each carried its own
16	// enumeration, its own owner filter, its own empty-enumeration guard, its own
17	// home/canon/archived/fork/excluded skips and its own declaration read per repo. The
18	// freshness half's header claimed it "takes coverage as given" while in fact
19	// re-deriving it, on another cadence, in another process — so the two classifications
20	// could disagree and did: `exclude` was applied at different points (an excluded repo
21	// that still carried a declaration read `covered` to one and `out of scope` to the
22	// other), and each half's `unknown` failed its own run knowing nothing of the other's.
23	// The roster is now built ONCE and both halves consume it, so a repo has one
24	// membership verdict and the report has one failure boundary.
25	//
26	// WHAT IS STILL SEPARATE, deliberately: the two QUESTIONS. Coverage answers in an issue
27	// family of its own; freshness answers on the report and files nothing, because the
28	// dashboard already carries that fact from the same source (#1854). Each keeps its own
29	// remedies and its own section of the report, in its own module. This file owns the walk
30	// and nothing else.
31	//
32	// UNKNOWN IS PER-QUESTION, which is the one behaviour the merge changes. A declaration
33	// that cannot be read or parsed is unknown to BOTH halves — it is the input they share.
34	// A mount probe that fails (the scheduler read, canon's compare) is unknown to the
35	// FRESHNESS half alone: the coverage half already read that repo's declaration
36	// successfully and keeps its verdict. Either kind of unknown fails the run, so nothing
37	// is downgraded to silence; what changes is that a compare outage no longer erases a
38	// repo from the coverage picture.
39	//
40	// Two rules kept from both predecessors:
41	//   - an indeterminate repo is UNKNOWN, never a finding — no issue is opened for it,
42	//     and the run fails so the cause escalates;
43	//   - an unreadable/absent claudinite-fleet-sheepdog config aborts the sweep — absence is not consent
44	//     to cover everything with no exclusions.
45	//
46	// Dependency-free (global fetch, Node 20+); read-only toward every repo except the
47	// enforcer, where it writes the two issue families and their labels.
48	
49	import { appendFileSync } from 'node:fs';
50	import { pathToFileURL } from 'node:url';
51	import { makeGh, paged, readDeclaration, isDormant, ensureLabel, DECLARATION } from '../../fleet-api.mjs';
52	import { parseSheepdogConfig } from '../../fleet-config.mjs';
53	import { missingFleetTokenError } from '../../fleet-token.mjs';
54	import * as adoption from './adoption-issues.mjs';
55	import * as freshness from './freshness.mjs';
56	
57	// --- the roster walk ----------------------------------------------------------
58	
59	// One entry per repo under the owner, carrying FACTS rather than a verdict: the two
60	// halves disagree about what some of those facts mean (an excluded repo is still
61	// `covered` to the coverage question and out of scope to the freshness one), and a
62	// single pre-chewed state would have to pick a winner. The views below do the
63	// interpreting, each for its own question.
64	//
65	// Reads per repo: the declaration, once — the read both halves needed and each used to
66	// make separately. Plus two more (scheduler workflow, canon compare) for the members
67	// the freshness half actually measures, and canon's version numbers, which the shared
68	// `canonVersions` reader fetches once per distinct pack across the whole walk.
69	export async function buildRoster(gh, repos, {
70	  home, canonRepo, canonBranch, exclude, canonVersions,
71	}) {
72	  const roster = [];
73	  for (const r of repos.sort((a, b) => a.name.localeCompare(b.name))) {
74	    const fullName = r.full_name.toLowerCase();
75	    const entry = {
76	      fullName,
77	      displayName: r.full_name,
78	      isHome: fullName === home.toLowerCase(),
79	      isCanon: fullName === canonRepo.toLowerCase(),
80	      archived: Boolean(r.archived),
81	      fork: Boolean(r.fork),
82	      excluded: exclude.has(fullName),
83	      declaration: null,
84	      declarationError: null,
85	      dormant: false,
86	      freshness: null,
87	      freshnessError: null,
88	    };
89	    roster.push(entry);
90	
91	    // The enforcer is not censused and not swept; an archived repo or a fork is
92	    // neither. Nothing below would be read for any of them, so nothing is.
93	    if (entry.isHome || entry.archived || entry.fork) continue;
94	
95	    // The declaration is READ, not merely probed for existence: dormancy and the
96	    // stamp both live inside it. An unparsable one is UNKNOWN rather than uncovered,
97	    // because a file that cannot be read says nothing.
98	    try {
99	      entry.declaration = await readDeclaration(gh, r.full_name);
100	    } catch (e) {
101	      entry.declarationError = e.message;
102	      continue;
103	    }
104	    if (entry.declaration === null) continue;   // uncovered — the coverage half's subject
105	    entry.dormant = isDormant(entry.declaration);
106	
107	    // Which members the freshness half measures: covered, in scope, and neither the
108	    // enforcer nor canon. A DORMANT member is measured like any other — dormancy stops
109	    // its scheduler, not its clock, and a mount three engine versions behind is behind
110	    // whether or not anything there is still running. What its declaration does buy it
111	    // is narrower and is applied inside the classification: a stopped scheduler is not
112	    // counted against it.
113	    if (entry.isCanon || entry.excluded) continue;
114	
115	    try {
116	      const mount = await freshness.probeMount(gh, r.full_name, entry.declaration, { canon: canonVersions });
117	      entry.freshness = freshness.classifyFreshness({ ...mount, dormant: entry.dormant });
118	    } catch (e) {
119	      entry.freshnessError = e.message;
120	    }
121	  }
122	  return roster;
123	}
124	
125	// --- the two views (pure) -----------------------------------------------------
126	
127	// The coverage question's buckets. Note what is NOT consulted: `isCanon` (canon carries
128	// a declaration and is an ordinary covered member here) and `freshnessError` (a mount
129	// this half never asked about). `excluded` matters only once a repo turns out to be
130	// uncovered — an excluded repo that still carries a declaration is covered, and saying
131	// otherwise would report a repo as missing something it has.
132	export function coverageView(roster) {
133	  const covered = []; const dormant = []; const uncovered = []; const optedOut = []; const skipped = []; const unknown = [];
134	  for (const e of roster) {
135	    if (e.isHome) continue;                       // named in the summary, not censused
136	    if (e.archived || e.fork) { skipped.push(`${e.displayName} (${e.archived ? 'archived' : 'fork'})`); continue; }
137	    if (e.declarationError) { unknown.push(`${e.displayName} — ${e.declarationError}`); continue; }
138	    if (e.declaration !== null) (e.dormant ? dormant : covered).push(e.fullName);
139	    else if (e.excluded) optedOut.push(e.fullName);
140	    else uncovered.push(e.fullName);
141	  }
142	  return { covered, dormant, uncovered, optedOut, skipped, unknown };
143	}
144	
145	// The freshness question's buckets. `outOfScope` carries the repos this half does not
146	// measure WITH their reasons, since the report names every repo rather than only the
147	// failures.
148	//
149	// `dormant` is a LABEL here, not an exit: a dormant member is bucketed as fresh or
150	// unhealthy like any other, and named in `dormant` as well so the summary can say which
151	// of the members it just reported will not repair themselves. It used to be an exit, and
152	// the cost was that a dormant member's mount could fall arbitrarily far behind canon with
153	// the roster saying nothing at all about it.
154	export function freshnessView(roster) {
155	  const fresh = []; const unhealthy = []; const dormant = []; const outOfScope = []; const unknown = [];
156	  for (const e of roster) {
157	    if (e.isHome || e.isCanon) continue;          // named in the summary, never measured
158	    if (e.archived || e.fork) { outOfScope.push(`${e.displayName} (${e.archived ? 'archived' : 'fork'})`); continue; }
159	    if (e.excluded) { outOfScope.push(`${e.displayName} (excluded)`); continue; }
160	    if (e.declarationError) { unknown.push(`${e.displayName} — ${e.declarationError}`); continue; }
161	    if (e.declaration === null) { outOfScope.push(`${e.displayName} (uncovered — the adoption half's subject)`); continue; }
162	    if (e.dormant) dormant.push(e.fullName);
163	    if (e.freshnessError) { unknown.push(`${e.displayName} — ${e.freshnessError}`); continue; }
164	    if (e.freshness.state === freshness.FRESH) fresh.push({ fullName: e.fullName, detail: e.freshness.detail });
165	    else unhealthy.push({ fullName: e.fullName, dormant: e.dormant, ...e.freshness });
166	  }
167	  return { fresh, unhealthy, dormant, outOfScope, unknown };
168	}
169	
170	// --- main --------------------------------------------------------------------
171	
172	// Exported so the fleet-roster task's worker can invoke the sweep in-process rather
173	// than reimplementing it; the CLI guard below keeps the standalone run.
174	export async function main() {
175	  const token = process.env.FLEET_GITHUB_TOKEN;
176	  const home = process.env.GITHUB_REPOSITORY;
177	  if (!token) {
178	    throw missingFleetTokenError('fleet-roster',
179	      'The default GITHUB_TOKEN sees only this repo and cannot sweep the fleet.');
180	  }
181	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
182	  const gh = makeGh(token);
183	
184	  // Read the fleet config from this (claudinite-fleet-sheepdog) repo's claudinite-fleet-sheepdog pack entry.
185	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
186	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
187	    throw new Error(`the claudinite-fleet-sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
188	  }
189	  let cfg;
190	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
191	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
192	  }
