226	      : '**Fresh:** none',
227	    dormant.length ? `**Dormant (scheduler stopped by declaration — measured like any other member, but will not self-heal):** ${dormant.join(', ')}` : '',
228	    outOfScope.length ? `**Out of scope (not covered members):** ${outOfScope.join(', ')}` : '',
