1	// The claudinite-fleet-sheepdog sweeps' cross-repo GitHub REST client. Dependency-free (global
2	// fetch, Node 20+). This is the ONE place a Claudinite process talks GitHub over
3	// raw REST with a token, and it is deliberately confined to the sweeps — the
4	// account-spanning audits that must enumerate EVERY repo the owner owns
5	// (`/user/repos`), which a session-scoped connection structurally cannot see. They run
6	// Action-side as their tasks' preprocessing, with a
7	// fine-grained PAT; nothing in the daily-maintenance process imports this (that
8	// process is MCP-native and carries no REST client). It knows nothing about any
9	// specific pack: it is the generic "talk to many repos" layer, no more.
10	//
11	// It is READ-ONLY toward members but for ONE primitive — `putFile`, which the
12	// pack-seed sweep uses to land a declaration this fleet wants in every member.
13	// Keeping the write to a single named function is deliberate: "what can this module
14	// change in someone else's repo" then has exactly one answer to read.
15	
16	import { isDormant } from '../claudinite-tasks/shared-code/dormancy.mjs';
17	import { forbiddenHint } from './fleet-token.mjs';
18	import { SETTINGS_FILE, SETTINGS_FILES } from '../../engine/settings-file.mjs';
19	
20	const API = 'https://api.github.com';
21	
22	// The tracked declaration every member carries — the file the sweeps read a member's
23	// membership, versions and dormancy out of. Named once here because all three sweeps
24	// name it, and re-exported from the engine so the rename (#1252) has one home: over
25	// the API there is no disk to probe, so a read tries both names in SETTINGS_FILES
26	// order and a member that has not run the record yet still answers.
27	export const DECLARATION = SETTINGS_FILE;
28	
29	// Dormancy, re-exported from the tasks pack's published surface rather than re-tested
30	// here. It is a property of a member's SCHEDULER, and the test has to be the same one
31	// that scheduler used to stop itself — a sweep with its own private notion of dormancy
32	// would nag exactly the repos that had already opted out, which is the whole failure
33	// this exists to prevent. What it licenses is narrow: a stopped scheduler is not a sick
34	// member, and nothing more. Every other question a sweep asks — is the mount current,
35	// is the declaration readable — is asked of a dormant member exactly as of any other.
36	export { isDormant };
37	
38	
39	export function makeGh(token) {
40	  return async function gh(path, { method = 'GET', body } = {}) {
41	    const res = await fetch(`${API}${path}`, {
42	      method,
43	      headers: {
44	        Authorization: `Bearer ${token}`,
45	        Accept: 'application/vnd.github+json',
46	        'X-GitHub-Api-Version': '2022-11-28',
47	        ...(body ? { 'Content-Type': 'application/json' } : {}),
48	      },
49	      body: body ? JSON.stringify(body) : undefined,
50	    });
51	    const text = await res.text();
52	    let json = null;
53	    try { json = text ? JSON.parse(text) : null; } catch { /* non-JSON body */ }
54	    return { status: res.status, json };
55	  };
56	}
57	
58	// A failure the FLEET TOKEN'S GRANT explains — a read or a write GitHub refused
59	// because the PAT lacks the scope, not because anything is wrong with the code.
60	// Tagged rather than described, because the tag survives being re-thrown and the
61	// wording does not: a worker's top-level catch prints the triage marker off
62	// `e.triage` (`fleetWorkerFailed`), so the item parks at
63	// `task:needs-human-action` — a person adds a scope — instead of at `failure`,
64	// where it would wait for someone to read a stack trace that says nothing.
65	export function grantError(message) {
66	  const e = new Error(message);
67	  e.triage = 'action';
68	  return e;
69	}
70	
71	// Every worker's `main().catch(…)`. Prints the marker the executor routes on when
72	// the error carries a triage tag, then fails the run as before.
73	export function fleetWorkerFailed(name, e) {
74	  console.error(`${name} failed: ${e.message}`);
75	  if (e?.triage) console.error(`claudinite-needs-human: ${e.triage} — ${e.message}`);
76	  process.exit(1);
77	}
78	
79	export async function paged(gh, path) {
80	  const sep = path.includes('?') ? '&' : '?';
81	  const all = [];
82	  for (let page = 1; ; page += 1) {
83	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
84	    if (status !== 200 || !Array.isArray(json)) {
85	      const why = `GET ${path} page ${page} failed with status ${status}`;
86	      // A 403 is a grant short one permission, not a broken endpoint: name which one,
87	      // or the run reports a bare status a hundred requests into a sweep (#1030).
88	      throw (status === 401 || status === 403)
89	        ? grantError(`${why}${status === 403 ? forbiddenHint(path) : ' — the fleet PAT is unusable'}`)
90	        : new Error(why);
91	    }
92	    all.push(...json);
93	    if (json.length < 100) return all;
94	  }
95	}
96	
97	// --- the enforcer repo's own issue surface -----------------------------------
98	// Both issue families the roster sweep converges (coverage and freshness) file a
99	// labelled issue per finding IN THE ENFORCER REPO. The label ensure and the
100	// labelled-issue read are identical between them — only the open/close POLICY
101	// differs, and that stays in each family's module, where its semantics are legible.
102	// These two are the shared floor.
103	
104	// Idempotent: 422 is "already exists", which is the state we wanted.
105	export async function ensureLabel(gh, repo, name, { color, description }) {
106	  const { status } = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
107	  if (status !== 201 && status !== 422) throw new Error(`creating label ${name} returned ${status}`);
108	}
109	
110	// Every issue ever carrying the label, open and closed, PRs filtered out — a
111	// sweep needs the closed ones to tell "converged" from "never opened", and to
112	// honour a close the owner made deliberately.
113	export async function labeledIssues(gh, repo, label) {
114	  const all = (await paged(gh, `/repos/${repo}/issues?labels=${label}&state=all`)).filter((i) => !i.pull_request);
115	  return { open: all.filter((i) => i.state === 'open'), closed: all.filter((i) => i.state === 'closed') };
116	}
117	
118	// 200 → true, 404 → false, anything else → error (the caller decides what an
119	// indeterminate result means).
120	export async function fileExists(gh, fullName, path) {
121	  const { status } = await gh(`/repos/${fullName}/contents/${path}`);
122	  if (status === 200) return true;
123	  if (status === 404) return false;
124	  throw new Error(`marker check ${fullName}:${path} returned ${status}`
125	    + (status === 403 ? forbiddenHint(`/repos/${fullName}/contents/`) : ''));
126	}
127	
128	// One file's text and its blob sha, or null when the repo has no such file. The sha
129	// is what a later write passes back as its precondition (see putFile), so reading and
130	// writing a file is one read here and one write there — never a second read that could
131	// see a different commit.
132	export async function readFile(gh, fullName, path) {
133	  const res = await gh(`/repos/${fullName}/contents/${encodeURI(path)}`);
134	  if (res.status === 404) return null;
135	  if (res.status !== 200 || typeof res.json?.content !== 'string') {
136	    throw new Error(`${fullName}:${path} returned ${res.status}`
137	      + (res.status === 403 ? forbiddenHint(`/repos/${fullName}/contents/`) : ''));
138	  }
139	  return { text: Buffer.from(res.json.content, 'base64').toString('utf8'), sha: res.json.sha };
140	}
141	
142	// One repo's parsed declaration, or null when it has none (uncovered). Anything
143	// else — an unreadable response, an unparsable body — THROWS, because a sweep that
144	// cannot read a member's declaration knows nothing about it, and "I could not read
145	// it" must never quietly become "it says nothing". Shared by the sweeps that need
146	// what is INSIDE the file (the stamp, the dormancy flag) rather than only that it
147	// exists. `withFile` returns `{ config, text, sha }` instead — the parsed settings, the
148	// exact bytes, and the write precondition, all from the ONE response, for a sweep that
149	// goes on to write the file back: a second read could see a different commit.
150	export async function readDeclaration(gh, fullName, path = null, { withFile = false } = {}) {
151	  // No explicit path: try each settings-file name in turn, so a member the rename
152	  // record has not reached is read from the name it still carries.
153	  let file = null;
154	  for (const candidate of path ? [path] : SETTINGS_FILES) {
155	    file = await readFile(gh, fullName, candidate);
156	    if (file !== null) { path = candidate; break; }
157	  }
158	  if (file === null) return null;
159	  let config;
160	  try {
161	    config = JSON.parse(file.text);
162	  } catch (e) {
163	    throw new Error(`unparsable ${path}: ${e.message}`);
164	  }
165	  return withFile ? { config, text: file.text, sha: file.sha } : config;
166	}
167	
168	// Write one file back to a repo's default branch, guarded by the sha the read
169	// returned: a 409 means the file moved under us, so the caller's decision was made
170	// against content that no longer exists and this run simply does not write it (the
171	// next run re-reads and decides again). The ONE write primitive that touches another
172	// repo — every other call in this module reads.
173	export async function putFile(gh, fullName, { path, text, sha, message }) {
