1	// The scheduler run (tasks-dispatch DESIGN §5) — the whole of the queue's
2	// scheduled machinery, and a stateless loop: at every tick it asks every declared
3	// task, through the task's own preconditions, whether it wants to run now, and
4	// files an issue only on a yes (decision §15.33).
5	//
6	// Four jobs: ASK — every task on the schedule, through the injectable `evaluate`
7	// seam; a yes creates the work item, a no is a log line, and a read the scheduler
8	// cannot make fails OPEN and creates the item for the executor to decide; READY
9	// blocked items whose dependencies have resolved and whose not-before has passed;
10	// ADOPT the issues somebody marked for implementation; and RECLAIM dead executor
11	// claims. The executor still re-evaluates at pick (§6.4). The engine keeps no
12	// memory of an ask: a task's cadence is a condition over its own run history,
13	// read off the queue, so a decline is simply asked again at the next tick and
14	// nothing durable can eat a run. One invariant is the engine's own — ONE LIVE ITEM
15	// PER TASK: while a task's item is blocked, waiting or running, it is not asked.
16	// Beside job 1, the reap of a standing item whose task is no longer declared at
17	// HEAD.
18	//
19	// The run's last act is the DRAIN GATE (§15.30): it reports whether it left
20	// anything pickable, and the workflow's drain job starts an executor only then —
21	// an idle tick costs this one run rather than two.
22	//
23	// `planSchedulerRun` is the decision core, kept injectable so it tests with fixtures; the
24	// CLI shell below wires the GitHub reads, the signal-collection seam, and applies the ops.
25	
26	import { pathToFileURL } from 'node:url';
27	import { isSuspended, suspendedNotice } from './suspend.mjs';
28	import { EXECUTING_LEASH_MS } from './leases.mjs';
29	import { swapStatus } from './apply-status.mjs';
30	import { isReleasable } from './readiness.mjs';
31	import { isQueueItem } from './read.mjs';
32	import { pickOrder } from './executor.mjs';
33	import { lastLivenessAt } from './heartbeat.mjs';
34	import {
35	  WORK_PREFIX, BLOCKED, READY, TASK_OBSOLETE,
36	  NEEDS_HUMAN_DECISION, LIVE_STATUSES,
37	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
38	  isStatus, statusOf,
39	  QUEUE_LABELS, EPISODE_MARKER, workItemTitle, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
40	  workItemBody, labelNames, hasLabel,
41	  ORIGIN_AD_HOC, ORIGIN_PLANNED, ORIGIN_LABELS, REQUEST_LABEL, parseRequestFields,
42	  parseBlockedBy, withMachineBlock,
43	} from './work-item.mjs';
44	import { REQUEST_TASK_ID } from '../built-in-tasks.mjs';
45	import { taskSignalNames, isScheduledTask } from '../task-contract.mjs';
46	import { evaluatePreconditions } from '../precondition-policy.mjs';
47	import { RUN_HORIZON_DAYS } from '../signals/index.mjs';
48	
49	// The scheduler run owns the executing-leash reclaim because it is deterministic and
50	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
51	// ~25h (DESIGN §11, owner decision 6).
52	export { EXECUTING_LEASH_MS };
53	
54	const ms = (t) => (t == null ? null : new Date(t).getTime());
55	
56	// The ops `planSchedulerRun` emits, each a label-and-body mechanic the shell applies:
57	//   { kind: 'dedupe',  issue, reason }            close, task:obsolete
58	//   { kind: 'create',  pack, task, labels, body } a task's standing item
59	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
60	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
61	//   { kind: 'adopt',   request, title, body, … }  a marked issue becomes an item
62	//   { kind: 'supersede', issue, request, reason } a parked prior run of a re-ask
63	//   { kind: 'retire-orphan', issue, reason }      a standing item whose task is gone closes
64	//
65	// Beside the ops, `asked`: one `{ task, verdict, reason }` per task this run asked,
66	// `verdict` being `go`, `no` or `fail-open` — the run's log, and the whole record
67	// of a decline, since nothing durable is written for one.
68	//
69	// `items` is every `[claudinite-work]` issue the shell fetched (state=all back to
70	// the run-history horizon, open for the rest), each `{ number, title, body, state,
71	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
72	// state of a `Blocked-by` target that may not be a work item at all; an unknown
73	// number is never treated as closed, so an unreadable blocker delays rather than
74	// releases (the convergence-not-prevention posture).
75	//
76	// `evaluate(task)` is the ask: async, returning the precondition's verdict `{
77	// run, reason, … }` or `{ error }` where the scheduler could not decide — a
78	// missing credential, a failed signal read, a throwing term. An error FAILS OPEN:
79	// the item is created and the executor, which holds the credentials, decides at
80	// pick. It is REQUIRED wherever a task is asked — a fixture with no seam and a
81	// task to ask is a fixture that has not said what the task answers.
82	export async function planSchedulerRun({
83	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
84	  stateOf = () => null, evaluate = null,
85	}) {
86	  const nowMs = ms(now);
87	  const ops = [];
88	  const asked = [];
89	  // REPO SHAPE IS NOT A PRECONDITION (task-preconditions DESIGN, "What is not a
90	  // precondition"). "This repo ships the store pipeline", "this repo is a canon
91	  // home with a fleet token" are facts adoption settled, not questions worth
92	  // re-asking every tick — so a repo that carries a pack but not one task's
93	  // subject names that task in `taskScheduler.disabledTasks` and it is never
94	  // asked. Read here rather than at pick, because the cheapest run is the one
95	  // that files no item at all.
96	  const disabled = new Set(schedule?.disabledTasks ?? []);
97	  const closedByThisRun = new Set();
98	
99	  // ---- the orphan reap ----------------------------------------------------
100	  // A blocked standing item whose `<pack>/<task>` is not declared at HEAD can
101	  // never execute — job 1 matches its family title-exact on the declared id, so a
102	  // legacy pack spelling is invisible to it, and job 2 would otherwise ready the
103	  // item at its Not-before and hand an executor a task path that is not on disk.
104	  // Guarded on a non-empty task list so an unreadable declaration reaps nothing,
105	  // and scoped to BLOCKED so nothing in flight is touched — a ready orphan is
106	  // picked within the tick and parks for a human, which is visible rather than
107	  // silent. Items waiting on a blocker are untouched: they are somebody's
108	  // dependency, not a schedule's.
109	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
110	  for (const item of items) {
111	    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
112	    const parsed = parseWorkItemTitle(item.title);
113	    if (!parsed || parsed.qualifier !== null) continue;
114	    const key = `${parsed.pack}/${parsed.task}`;
115	    if (parseWorkItemBody(item.body).blockedBy.length) continue;
116	    if (byId.has(key) && !disabled.has(key)) continue;
117	    closedByThisRun.add(item.number);
118	    ops.push({
119	      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
120	      reason: disabled.has(key)
121	        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
122	          + 'asked here. Remove it from that list to bring the task back.'
123	        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
124	          + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
125	    });
126	  }
127	
128	  // ---- job 1: ask every task on the schedule; a yes files the item ----------
129	  const live = (i) => LIVE_STATUSES.some((s) => isStatus(i, s));
130	  for (const task of tasks) {
131	    // A task whose declaration says `trigger: 'request'` runs only from an item
132	    // somebody created (DESIGN §5, §8): the schedule never asks it, and its items
133	    // keep their own titles.
134	    if (!isScheduledTask(task.decl)) continue;
135	    const key = `${task.pack}/${task.id}`;
136	    if (disabled.has(key)) continue;
137	    const title = workItemTitle({ pack: task.pack, task: task.id });
138	    // The family is title-EXACT, which is also what makes it STRUCTURALLY the
139	    // standing family (§15.26): this task is on the schedule and the title carries
140	    // no qualifier, so a fan-out target or a request — qualified, both of them — is
141	    // a different title and neither suppresses nor consumes an occurrence (§3).
142	    const family = items.filter((i) => (i.title ?? '').trim() === title);
143	    // ONE LIVE ITEM PER TASK, the engine's one invariant: an open item that is
144	    // blocked, waiting or running is the task's current occurrence, and the task is
145	    // not asked while it stands. A PARKED item is not live — it is a person's inbox
146	    // or a fault on record — and whether it holds the task is the task's own
147	    // declaration (`last-run-not-failed`), never the engine's: absent that term the
148	    // next occurrence is filed beside the park, which the dedupe below must never
149	    // mistake for a duplicate.
150	    const open = family
151	      .filter((i) => i.state === 'open' && !closedByThisRun.has(i.number) && live(i))
152	      .sort((a, b) => a.number - b.number);
153	
154	    // F16 self-heal, FIRST: nothing documents that a REST list from another node
155	    // sees a creation seconds old, so a stale list can let a duplicate standing
156	    // item through. Assume it will happen rather than that it won't — close every
157	    // live family item but the oldest. Serialized by the scheduler run's concurrency
158	    // group, so this can never race itself.
159	    for (const dup of open.slice(1)) {
160	      closedByThisRun.add(dup.number);
161	      ops.push({
162	        kind: 'dedupe', issue: dup.number, pack: task.pack, task: task.id,
163	        reason: `a duplicate standing item for ${task.pack}/${task.id} — #${open[0].number} is this task's standing item`,
164	      });
165	    }
166	    if (open.length) continue; // the standing item already exists
167	
168	    if (!evaluate) throw new Error(`planSchedulerRun has a task to ask (${key}) and no evaluate seam to ask it through`);
169	    const verdict = (await evaluate(task)) ?? {};
170	    if (verdict.error) {
171	      // Fail open: never fewer runs because a read failed — the executor, which
172	      // holds the credentials, decides at pick (§6.4).
173	      asked.push({ task: key, verdict: 'fail-open', reason: verdict.error });
174	    } else if (verdict.run !== true) {
175	      // No work, no item, nothing written: the next tick asks again.
176	      asked.push({ task: key, verdict: 'no', reason: verdict.reason || 'no work' });
177	      continue;
178	    } else {
179	      asked.push({ task: key, verdict: 'go', reason: verdict.reason || '' });
180	    }
181	    ops.push({
182	      kind: 'create', pack: task.pack, task: task.id, title,
183	      // THE ORIGIN, worn for the item's whole life beside whatever status it holds
184	      // (DESIGN §3): the schedule filed this one, so it is `planned`.
185	      labels: [ORIGIN_PLANNED, READY],
186	      body: workItemBody({
187	        taskPath: task.taskPath,
188	        context: verdict.error ? [`The scheduler could not decide this occurrence (${verdict.error}); the executor decides at pick.`] : [],
189	      }),
190	      notBefore: null,
191	    });
192	  }
193	
194	  // ---- job 2: ready whatever is due (any origin) --------------------------
195	  // The only site that ever releases a blocked item (§15.19, reversed by
196	  // §15.31 / #1373): a converge writes only to the item it holds, so nothing
197	  // else asks this question.
198	  for (const item of items) {
199	    if (closedByThisRun.has(item.number)) continue;
200	    if (isReleasable(item, { stateOf, nowMs })) ops.push({ kind: 'ready', issue: item.number });
201	  }
202	
203	  // ---- job 4: adopt the issues somebody marked (DESIGN §16.3, §16.1) ------
204	  // Label mechanics like the other three: no precondition, no signal, and no
205	  // judgment about WHETHER the marked issue may run — that verdict is the request
206	  // task's precondition, at pickup, where every verdict is.
207	  //
208	  // THE MARKED ISSUE IS THE ITEM. Adoption files nothing: it appends the machine
209	  // block to the issue's own body and applies the first status, and the whole
210	  // lifecycle then plays out where the person is already looking. `requests` is
211	  // every open issue wearing `task:origin:ad-hoc` with NO status — that combination
212	  // is the whole of the exactly-once guard, and any status at all (live, parked or
213	  // terminal) holds the mark until a person clears it. So there is no prior item to
214	  // wait on and none to supersede: an impatient re-ask mid-run is structurally
215	  // nothing, because there is no second label to apply.
216	  //
217	  // Adoption needs the task it targets to exist at HEAD; where it does not — an
218	  // engine older than the mode, or a `Task:` naming something this repo does not
219	  // carry — the mark simply waits, which is what every other "not yet capable"
220	  // state here does.
221	  const byTaskId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
222	  for (const req of requests) {
