224	    if (req.state !== 'open' || !marked || statusOf(req) !== null) continue;
225	
226	    // The parameters ride the person's own text, re-read and re-gated at every
227	    // adoption (§16.7): the body is author-editable where a label was
228	    // platform-write-gated, so `Task:`, `Model:` and `Automerge:` are honoured only
229	    // for an author who holds push access. An ungated ask still runs — at the
230	    // default task and model, and authorized to land nothing.
231	    const asked = parseRequestFields(req.body, { gated: req.authorHasPush === true });
232	    const task = byTaskId.get(asked.task ?? REQUEST_TASK_ID) ?? null;
233	    if (!task) continue;
234	    // WHAT THE REQUEST WAITS ON (§16.11). A marked issue may name its blockers in
235	    // the same `Blocked-by:` field an item uses, which is how a follow-up filed
236	    // mid-session queues BEHIND the work in flight instead of racing it. A blocker
237	    // already closed holds nothing back — it is dropped here rather than carried and
238	    // immediately released. `Not-before:` rides the same rule, for the item's other
239	    // wait field: a deferred request waits on a moment as well as on an issue.
240	    const blockedBy = asked.blockedBy.filter((n) => stateOf(n) !== 'closed');
241	    const notBefore = asked.notBefore && ms(asked.notBefore) > nowMs ? asked.notBefore : null;
242	    ops.push({
243	      kind: 'adopt',
244	      request: req.number,
245	      task: `${task.pack}/${task.id}`,
246	      status: blockedBy.length || notBefore ? BLOCKED : READY,
247	      // The block is the machine's half of a body the human owns and keeps editing,
248	      // so it is written whole here and rewritten in place after that.
