307	// --- the forced wake (DESIGN §8) ----------------------------------------------
308	
309	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
310	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
311	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
312	// the member wakes its own items with its own token. The enforcer therefore needs
313	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
314	// the enforcer dispatches and the member executes.
315	//
316	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
317	// tasks, so a caller spanning many members never has to know any one member's pack
318	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
319	// report counts only what it woke reads as coverage it did not have.
320	//
321	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
322	// alone and reported as `already`, never re-woken — an episode boundary dropped on
323	// a live claim is exactly the livelock F18 describes.
324	//
325	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
326	// task that completes closes its item, and the next one appears only when the
327	// task next says yes — so between the two there is nothing to wake, and that gap
328	// is the common case rather than an edge: a daily task is missing its item for
329	// most of the day. A force that reported "nothing to wake" there would fail on
330	// most members most of the time, which is precisely what a fleet-wide converge
331	// lever must not do. The minted item is an ordinary standing item — same title,
332	// no qualifier — stamped `Woken:` so the task's cadence terms hold on it (a
333	// person's wake stands in for the cadence) while everything else it requires
334	// still applies; it is the task's live item, so the scheduler asks nothing beside it.
335	//
336	// A WOKEN-GATED task is the exception, and never minted: it has no standing item
337	// to stand in for — an item exists only because an issue named the task (a
338	// verification's `Task:` line, a marked request), and a bare one carries nothing
339	// its worker can read, so it can only park (#1721). Its items keep their own
340	// titles, so the force reaches them by the task path in the machine block: every
341	// open one not in flight is woken, and none at all is reported, never papered
342	// over with a mint.
343	export function planWake(spec, tasks = [], items = []) {
344	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
345	  const wake = []; const create = []; const already = []; const unmatched = [];
346	  for (const id of ids) {
347	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
348	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
349	    if (owners.length !== 1) {
350	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
351	      continue;
352	    }
353	    const owner = owners[0];
354	    const { pack, id: task } = owner;
355	    if (!isScheduledTask(owner.decl)) {
356	      const routed = items.filter((i) => {
357	        if (i.state !== 'open') return false;
358	        const byPath = taskIdFromPath(parseWorkItemBody(i.body).taskPath);
359	        return !!byPath && byPath.pack === pack && byPath.task === task;
360	      });
361	      if (!routed.length) {
362	        unmatched.push({ id, why: `"${pack}/${task}" is not on the schedule and has no open item — nothing stands for it to mint, so an item exists only where an issue names the task` });
363	        continue;
364	      }
365	      for (const item of routed) {
366	        if (IN_FLIGHT.includes(statusOf(item))) already.push({ id, issue: item.number });
367	        else wake.push({ id: `${pack}/${task}`, issue: item.number });
368	      }
369	      continue;
370	    }
371	    const item = items.find((i) => {
372	      if (i.state !== 'open') return false;
373	      const parsed = parseWorkItemTitle(i.title);
374	      return parsed && parsed.pack === pack && parsed.task === task;
375	    });
376	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
377	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
378	    wake.push({ id: `${pack}/${task}`, issue: item.number });
379	  }
380	  return { wake, create, already, unmatched };
381	}
