383	// The Context a forced standing item carries. It says the force is the only reason
384	// the item exists, because the executor still evaluates the precondition at pick:
385	// a force that finds no work must roll with its reason on record, not invent work.
386	export const FORCED_WAKE_CONTEXT =
387	  'Minted by a force — this task had no open standing item at the time. The wake stands in for the task\'s cadence; every other condition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
