389	// The statuses that mean someone already holds this item — decoded, so an item any
390	// engine version filed answers the same. `running-agent` counts: the work is with a
391	// session, and waking would hand a second executor the same item.
392	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
