394	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
395	// Reads the work-item list, plans, applies. All GitHub access is the Action's
396	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
397	// said it is out of the recurring work should not pay for the list that proves it.
398	
399	// Every WORK ITEM, state=all, via the ISSUES list API — never the search index
400	// (S6/F11: search is eventually consistent, and a family list that misses a
401	// just-created item mints a duplicate standing item). Bounded by the scheduled
402	// families' need for closed history: closed items are only interesting back to the
403	// widest period, so the listing stops once it is past that.
404	//
405	// MEMBERSHIP IS `isQueueItem`, the shared predicate, and not the title prefix
406	// (#1497). An adopted marked issue IS an item under the one-issue model (DESIGN
407	// §16.1) and keeps the person's own title forever, so a prefix test drops exactly
408	// that class — and job 2 is the ONLY site that releases a blocked item, so an
409	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
410	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
411	// janitor already read the queue through this predicate; this list was the one that
412	// did not.
413	export async function listWorkItems(gh, repo, { since = null } = {}) {
414	  const out = [];
415	  for (let page = 1; ; page += 1) {
416	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
417	      + (since ? `&since=${encodeURIComponent(since)}` : '');
418	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
419	    // A page that could not be read is not the end of the list. Breaking on it
420	    // truncates the queue mid-pagination and the run plans against the remainder:
421	    // a standing item whose page never arrived reads as absent, and the run mints a
422	    // second one beside it.
423	    if (status !== 200 || !Array.isArray(json)) {
424	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
425	    }
426	    if (json.length === 0) break;
427	    for (const i of json) {
428	      if (i.pull_request) continue;
429	      if (!isQueueItem(i)) continue;
430	      out.push({
431	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
432	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
433	        updated_at: i.updated_at,
434	      });
435	    }
436	    if (json.length < 100) break;
437	  }
438	  return out;
439	}
