441	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
442	// filtered by label — never the search index, for the same reason the work-item
443	// list is not (S6/F11): a mark this list misses is a request that silently waits an
444	// hour, and one it misses TWICE is a request nobody notices was never picked up.
445	//
446	// The author's push permission comes back with each issue, because adoption gates
447	// the body's parameters on it (§16.7) and the payload's `author_association` is not
448	// that fact: `MEMBER` is any org member whatever their repo permission, and
449	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
450	// leaves the flag `null`, which gates the parameters off — the safe end of a field
451	// that chooses a task, a model, or the right to land a change without review.
452	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
453	  const out = [];
454	  const push = permissionOf ?? (async (login) => {
455	    const res = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
456	    if (res.status === 404) return false;
457	    if (res.status !== 200) return null;
458	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
459	  });
460	  const cache = new Map();
461	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
462	  // comma-separated list selects the issues carrying EVERY name on it — so asking
463	  // for both marks at once asks for issues wearing both, which nothing does. The
464	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
465	  // or in a template, decoded forever like every legacy spelling (§4), and that
466	  // costs a second listing rather than a wider one.
467	  const seen = new Map();
468	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
469	    for (let page = 1; ; page += 1) {
470	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
471	      const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
472	      // A list that could not be READ is not a list that is EMPTY, and the two are
473	      // indistinguishable downstream: adoption simply finds nothing to do and the run
474	      // reports success. Every request then waits for a person to notice, which is
475	      // the one thing this lane exists so nobody has to do.
476	      if (status !== 200 || !Array.isArray(json)) {
477	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
478	      }
479	      if (json.length === 0) break;
480	      for (const i of json) {
481	        if (i.pull_request) continue;
482	        // A filed work item wearing the mark is not a request awaiting adoption: it is
483	        // already an item, and re-adopting one would rewrite its body under the run
484	        // holding it.
485	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
486	        // ANY status means this mark has been adopted — the exactly-once guard (§16.3).
487	        // Filtering here rather than in the plan keeps the permission reads to the
488	        // issues actually awaiting adoption.
489	        if (statusOf(i) !== null) continue;
490	        // An issue wearing both spellings comes back from both listings; it is one
491	        // request, and adopting it twice would rewrite the body of the item the first
492	        // adoption just made.
493	        if (seen.has(i.number)) continue;
494	        const author = i.user?.login ?? null;
495	        if (author && !cache.has(author)) cache.set(author, await push(author));
496	        seen.set(i.number, {
497	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
498	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
499	        });
500	      }
501	      if (json.length < 100) break;
502	    }
503	  }
504	  out.push(...seen.values());
505	  return out;
506	}
