508	// Which `Blocked-by` targets this run still has to read. A target need not be a
509	// work item — a fan-in blocks on whatever its children are — so states come from
510	// the fetched items first and a direct read otherwise, and `known` is what has
511	// already been answered.
512	//
513	// A marked issue's blockers count the same way: adoption decides whether the item
514	// it births is born blocked or ready, and an unread state is never `closed`, so a
515	// missing read delays the request rather than releasing it (§16.11).
516	//
517	// Extracted from `main` so it can be called at all. Nothing else here drives
518	// `main`, whose body is I/O against a live Action, so an identifier it names and
519	// never imports resolves at run time or not at all — and the request half went
520	// three days without executing once, behind an adoption list that was always
521	// empty (#1354).
522	export function blockersToResolve(items, requests, known) {
523	  const wanted = new Set();
524	  for (const i of items) {
525	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
526	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
527	  }
528	  for (const r of requests) {
529	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
530	  }
531	  return wanted;
532	}
