668	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
669	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_RUNNING_EXECUTOR, op.to);
670	      if (op.to === READY) readied.add(op.issue);
671	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
672	    } else if (op.kind === 'adopt') {
673	      // THE ISSUE IS THE ITEM, so adoption writes to it rather than filing anything:
674	      // the machine block first, the status second. That order is what makes a torn
675	      // adoption safe — a block with no status is re-adopted by the next scheduler
676	      // run (which rewrites it), while a status with no block would name no task.
677	      const res = await gh(`/repos/${repo}/issues/${op.request}`, { method: 'PATCH', body: { body: op.body } });
678	      if (res.status !== 200) {
679	        console.log(`! could not adopt #${op.request}: its body could not be written (${res.status})`);
680	        process.exitCode = 1;
681	        continue;
682	      }
683	      if (op.origin) await addLabel(gh, repo, op.request, op.origin);
684	      await addLabel(gh, repo, op.request, op.status);
685	      await comment(gh, repo, op.request,
686	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
687	        + (op.blockedBy.length
688	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
689	          : '')
690	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
691	        + (op.merge
692	          ? `The run implements this issue and opens a pull request; it may land that pull request itself only when the diff sits inside the authorized policy (\`${op.merge}\`), and leaves a wider one for review. `
693	          : 'The run implements this issue and opens a pull request for review — it never merges one. ')
694	        + (op.ungated
695	          ? '\n\nThe `Task:`/`Model:`/`Automerge:` fields in this body were ignored: they are honoured only for an author with push access on this repository, so this run takes the defaults. '
696	          : '')
697	        + `To withdraw the request before it starts, remove the \`${ORIGIN_AD_HOC}\` mark and the status beside it.`);
698	      console.log(`- adopted #${op.request} for ${op.task} (${op.model ?? 'default model'}${op.blockedBy.length ? `, blocked on ${op.blockedBy.map((n) => `#${n}`).join(' ')}` : ''}${op.merge ? `, may merge: ${op.merge}` : ''})`);
699	    } else if (op.kind === 'supersede') {
700	      await comment(gh, repo, op.issue, op.reason);
701	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
702	      await closeIssue(gh, repo, op.issue, 'not_planned');
703	      console.log(`- superseded #${op.issue} — #${op.request} was re-marked`);
704	    } else if (op.kind === 'dedupe') {
705	      await comment(gh, repo, op.issue, op.reason);
706	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
707	      await closeIssue(gh, repo, op.issue, 'not_planned');
708	      console.log(`- deduped #${op.issue}`);
709	    } else if (op.kind === 'retire-orphan') {
710	      await comment(gh, repo, op.issue, op.reason);
711	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
712	      await closeIssue(gh, repo, op.issue, 'not_planned');
713	      console.log(`- reaped #${op.issue} — ${op.pack}/${op.task} is not declared at HEAD`);
714	    }
715	  }
716	
717	  if (!ops.length) console.log('- nothing to do: no task said yes, nothing is marked, nothing is due to be readied, no claim is dead');
718	
719	  // The forced wake, last: an item this run just instantiated is wakeable in the
720	  // same run, so a force never has to be pressed twice. The drain job that follows
721	  // picks up whatever this readies.
722	  const spec = process.env.CLAUDINITE_WAKE ?? '';
723	  if (spec.trim()) {
724	    const { wakeItem } = await import('./create-work-item.mjs');
725	    // Re-read: the ops above may have created or readied the very items named.
726	    const current = await listWorkItems(gh, repo, { since });
727	    const { wake, create, already, unmatched } = planWake(spec, tasks, current);
728	    for (const w of wake) {
729	      const res = await wakeItem(gh, repo, w.issue);
730	      if (res.ok) readied.add(w.issue);
731	      console.log(res.ok ? `- woke #${w.issue} ${w.id}` : `! could not wake #${w.issue} ${w.id}: ${res.error}`);
732	    }
733	    if (create.length) await ensureLabels(gh, repo, QUEUE_LABELS);
734	    for (const c of create) {
735	      const res = await createIssue(gh, repo, {
736	        title: workItemTitle({ pack: c.pack, task: c.task }),
737	        // `Woken:` is what lets the task's cadence terms hold at pick — a person's
738	        // wake stands in for the cadence — while everything else it requires
739	        // still applies (§5, §8).
740	        body: workItemBody({ taskPath: c.taskPath, context: [FORCED_WAKE_CONTEXT], woken: now.toISOString() }),
741	        // A forced mint stands in for the occurrence the schedule would have filed,
742	        // so it wears the same origin: the task IS on the schedule, and this item is
743	        // its current occurrence (§8).
744	        labels: [ORIGIN_PLANNED, READY],
745	      });
746	      if (res.number) {
747	        readied.add(res.number);
748	        console.log(`- created #${res.number} ${c.id} (forced: it had no open standing item)`);
749	      } else { console.log(`! could not create a work item for ${c.id}: ${res.status}`); process.exitCode = 1; }
750	    }
751	    for (const a of already) console.log(`- ${a.id} is already in flight on #${a.issue} — left alone`);
752	    for (const u of unmatched) console.log(`! nothing woken for "${u.id}": ${u.why}`);
753	    // A force that woke nothing is a failed force, and a green run saying so in a
754	    // log line is how it goes unnoticed by the fleet lever that pressed it.
755	    if (unmatched.length) process.exitCode = 1;
756	  }
757	
758	  // LAST, AFTER THE WAKE: whether this run leaves anything for an executor to do.
759	  await announcePickable(gh, repo, tasks, readied);
760	}
761	
762	// THE DRAIN GATE (§15.30). Every workflow run is a billed invocation whatever it
763	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
764	// executor only when this run's parting look at the queue found something
765	// pickable. On a quiet repo that is the difference between 24 executor runs a day
766	// and none.
767	//
768	// This is the run's LAST act, after the forced wake: a wake readies items, and a
769	// look taken before it would send the hour's forced work to the next cron fire.
770	//
771	// The delivery is unweakened by the gate. A label event may be lost, and what a
772	// lost event would have delivered is exactly what this look sees — the queue
773	// itself, read live, by the same pick rule the executor applies. Where the
774	// output cannot be written (a run outside Actions, an older member workflow that
775	// maps no output) the drain job's own default decides, and the run says which
776	// happened rather than going quiet about it.
777	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
778	// this run itself readied is the other, and the second needs no confirmation —
779	// GitHub's issue list is eventually consistent, so an item created milliseconds
780	// earlier can be absent from it (#1340). Trusting the read alone left a forced
781	// `update` sitting `task:ready` until the next cron fire on three members at once.
782	// Ordering stays the executor's job: this only decides whether to start one.
783	export function pickableCount(open, readiedThisRun = [], opts = {}) {
784	  const listed = pickOrder(open, opts).map((i) => i.number);
785	  return new Set([...listed, ...readiedThisRun]).size;
786	}
787	
788	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
789	  const { listOpenWorkItems } = await import('./read.mjs');
790	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
791	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
792	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
793	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
794	    scheduledOf: (id) => (byId.has(id) ? isScheduledTask(byId.get(id).decl) : null),
795	    pathTo: (p) => byPath.get(p) ?? null,
796	  });
797	  console.log(pickable
798	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
799	    : '- nothing pickable — no executor is dispatched this run');
800	  const out = process.env.GITHUB_OUTPUT;
801	  if (!out) return;
802	  const { appendFileSync } = await import('node:fs');
803	  appendFileSync(out, `pickable=${pickable ? 'true' : 'false'}\n`);
804	}
805	
806	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
807	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
808	// point that must be able to start the same run without being this module.
809	export { main as runSchedulerRun };
810	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
811	  main().catch((e) => { console.error(e); process.exit(1); });
812	}
813	
814	export { parseWorkItemTitle };
