1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import {
4	  isCovered, readFile, readDeclaration, putFile, isDormant, DECLARATION,
5	} from '../fleet-api.mjs';
6	import { isDormant as schedulerIsDormant } from '../../claudinite-tasks/shared-code/dormancy.mjs';
7	
8	// The pack's shared cross-repo REST layer. Membership is the tracked declaration
9	// file, the ONE probe every member carries whatever its mount shape
10	// (vendoring/DESIGN.md) — and the only shape the planner can plan for (activePacks
11	// is read from it). A mount marker WITHOUT a declaration is a half-adoption that
12	// must classify uncovered, so the census opens an adoption issue and it heals loudly.
13	
14	const ghWith = (paths200) => async (path) =>
15	  ({ status: paths200.some((p) => path.endsWith(`/contents/${p}`)) ? 200 : 404, json: {} });
16	
17	test('isCovered: the tracked declaration file is the single membership probe; a bare mount marker no longer covers', async () => {
18	  assert.equal(await isCovered(ghWith(['.claudinite-settings.json']), 'o/vendored-or-legacy-member'), true);
19	  assert.equal(await isCovered(ghWith(['.claudinite/mount/sync-claudinite.sh']), 'o/half-adopted'), false);
20	  assert.equal(await isCovered(ghWith([]), 'o/vanilla'), false);
21	});
22	
23	// --- the declaration read the sweeps share ------------------------------------
24	
25	const ghServing = (body, status = 200) => async () =>
26	  (status === 200 ? { status, json: { content: Buffer.from(body).toString('base64') } } : { status, json: null });
27	
28	test('readDeclaration: parses the member\'s declaration, null for uncovered, throws on anything indeterminate', async () => {
29	  assert.deepEqual(await readDeclaration(ghServing('{"packs":["basics"]}'), 'o/member'), { packs: ['basics'] });
30	  assert.equal(await readDeclaration(ghServing('', 404), 'o/vanilla'), null);
31	  // "I could not read it" must never become "it says nothing" — that is how a
32	  // dormant repo would get swept anyway, and an unreadable one silently dropped.
33	  await assert.rejects(() => readDeclaration(ghServing('', 500), 'o/flaky'), /returned 500/);
34	  await assert.rejects(() => readDeclaration(ghServing('{oops'), 'o/broken'), /unparsable/);
35	});
36	
37	test('readDeclaration: withFile hands back the bytes and the write precondition from the ONE response', async () => {
38	  // A sweep that decides from one read and then writes must pass the sha THAT read
39	  // returned — a second read could see a different commit, and the write would silently
40	  // land on top of it.
41	  const gh = async () => ({ status: 200, json: { content: Buffer.from('{\n  "packs": []\n}\n').toString('base64'), sha: 'blob1' } });
42	  const read = await readDeclaration(gh, 'o/member', DECLARATION, { withFile: true });
43	  assert.deepEqual(read.config, { packs: [] });
44	  assert.equal(read.text, '{\n  "packs": []\n}\n', 'the exact bytes, not a re-serialization');
45	  assert.equal(read.sha, 'blob1');
46	  assert.equal(await readDeclaration(async () => ({ status: 404 }), 'o/vanilla', DECLARATION, { withFile: true }), null);
47	  // readFile is the same read without the parse — used for source files, not settings.
48	  assert.deepEqual(await readFile(gh, 'o/member', 'engine/x.mjs'), { text: '{\n  "packs": []\n}\n', sha: 'blob1' });
49	});
50	
51	test('putFile: the ONE write, sha-guarded — a 403/404 names the missing scope, a 409 is not written', async () => {
52	  const seen = [];
53	  const responder = (status) => async (path, opts) => { seen.push({ path, ...opts }); return { status, json: { message: 'nope', commit: { sha: 'c1' } } }; };
54	
55	  assert.equal(await putFile(responder(200), 'o/member', { path: DECLARATION, text: 'x', sha: 's1', message: 'm' }), 'c1');
56	  assert.equal(seen[0].method, 'PUT');
57	  assert.equal(seen[0].body.sha, 's1', 'the read\'s sha is the precondition');
58	  assert.equal(Buffer.from(seen[0].body.content, 'base64').toString('utf8'), 'x');
59	
60	  // The token scope is the likely cause of both, and the message has to say so — named
61	  // from fleet-token.mjs's table rather than spelled here (#1030).
62	  for (const status of [403, 404]) {
63	    await assert.rejects(() => putFile(responder(status), 'o/m', { path: 'p', text: 'x', message: 'm' }), /missing Contents/);
64	  }
65	  // The file moved under the run: this run does not write, the next one re-decides.
66	  await assert.rejects(() => putFile(responder(409), 'o/m', { path: 'p', text: 'x', sha: 'stale', message: 'm' }), /changed under the sweep/);
67	  await assert.rejects(() => putFile(responder(500), 'o/m', { path: 'p', text: 'x', message: 'm' }), /returned 500/);
68	});
69	
70	test('the sweeps decide dormancy with the SCHEDULER\'s predicate, not a private copy', async () => {
71	  // A sweep with its own notion of dormancy would nag exactly the repos that had
72	  // already opted out — the member's own scheduler and the enforcer must agree on the
73	  // one test, so the pack re-exports the predicate published by the pack that owns the
74	  // scheduler rather than re-implementing it.
75	  assert.equal(isDormant, schedulerIsDormant);
76	  const asleep = '{"packs":[{"id":"claudinite-tasks","config":{"dormant":true}}]}';
77	  assert.equal(isDormant(await readDeclaration(ghServing(asleep), 'o/asleep')), true);
78	  assert.equal(isDormant(await readDeclaration(ghServing('{"packs":["claudinite-tasks"]}'), 'o/awake')), false);
79	  // A member the migration record has not reached still answers, so the sweep does not
80	  // spend a convergence window waking every repo that had asked to sleep.
81	  assert.equal(isDormant(await readDeclaration(ghServing('{"dormant":true}'), 'o/stale-spelling')), true);
82	});
83

